insert into public.videos (id, chapter_id, title, description, duration_seconds, thumbnail_url, source_url, notes_url, is_free, view_count, sort) values
  ('967186ce-fcc7-4495-a1c6-d29eaad7fad1', 'badca31f-e97e-4ff7-bdaf-072d8826cf8e', 'Describing Sets: Listing and Set-Builder Notation', 'Reviews what a set is and shows how to describe sets in words, by listing their elements and with set-builder notation, including finite, infinite and empty sets.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, true, 2192, 1),
  ('c89e294e-fac9-4976-856e-033a5be5bbeb', 'badca31f-e97e-4ff7-bdaf-072d8826cf8e', 'Subsets, Proper Subsets and Power Sets', 'Explains when one set is a subset of another, how subsets differ from proper subsets, and how to list a power set and count subsets using 2ⁿ.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, true, 4844, 2),
  ('f86a4f2e-5828-4077-b96e-f8fa8e4713a8', 'badca31f-e97e-4ff7-bdaf-072d8826cf8e', 'Set Operations and Venn Diagrams', 'Uses Venn diagrams to find unions, intersections, complements, differences and symmetric differences, then applies them to real-life counting problems.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, false, 3209, 3),
  ('a47edf2f-7080-4b41-aeeb-0981ca4029ae', '49196339-1a56-4778-9695-3837fbe86bc0', 'Rational Numbers and Repeating Decimals', 'Shows why every rational number has a terminating or repeating decimal and how to convert a repeating decimal such as 0.363636… into a fraction.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, false, 4359, 1),
  ('bb41a88a-cb27-4f17-a463-570e9925bf92', '49196339-1a56-4778-9695-3837fbe86bc0', 'Irrational Numbers and the Real Number Line', 'Introduces irrational numbers such as √2 and π, shows how to locate them on the number line, and explains how rational and irrational numbers together form the real numbers.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, false, 4137, 2),
  ('44844d9d-ec20-4d24-9d51-cdc11668922e', '49196339-1a56-4778-9695-3837fbe86bc0', 'Simplifying Radicals and Rationalizing Denominators', 'Practises simplifying square roots, adding and multiplying radicals, and removing radicals from denominators using conjugates.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, false, 1057, 3),
  ('3b891980-a1ac-4f5c-b95f-f1760181759d', '5c109745-2e83-498a-84ba-0f70d0f62e75', 'Reading: Life in a Big City', 'Reads a passage about city life and practises finding the main idea and supporting details about the advantages and disadvantages of living in urban areas.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, true, 3821, 1),
  ('1c7e1300-41f3-4a4e-8fc2-ba3a85aa5787', '5c109745-2e83-498a-84ba-0f70d0f62e75', 'Tag Questions and Wh-Questions', 'Explains how to form tag questions with the correct auxiliary verb and how to ask wh-questions, with practice on rising and falling intonation.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, true, 3445, 2),
  ('f9100d18-e0e0-4373-82f8-2ca1b837d2ff', '5c109745-2e83-498a-84ba-0f70d0f62e75', 'Simple Present vs. Present Continuous', 'Contrasts the simple present for habits and routines with the present continuous for actions happening now or around now, using examples from daily city life.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, false, 1034, 3),
  ('9c6d6b06-3d81-47c8-bdaf-3471dd7096ec', '81a1c026-a8e1-4235-bcc2-0f38f15c5b66', 'Reading: Learning Strategies That Work', 'Reads a passage on how successful students plan, take notes and review, and builds vocabulary through common study collocations.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, false, 473, 1),
  ('9a524b64-1d68-4c55-92b6-1d8f71f40256', '81a1c026-a8e1-4235-bcc2-0f38f15c5b66', 'Connectors, Sequence Words and Adverbs of Frequency', 'Shows how addition markers such as moreover and in addition, sequence words such as first and finally, and adverbs of frequency make writing about study habits clear and coherent.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, false, 3712, 2),
  ('cfbdd6ab-4122-4271-aa36-af66cc8642fc', '81a1c026-a8e1-4235-bcc2-0f38f15c5b66', 'Simple Past and Past Continuous Tenses', 'Explains how to use the past continuous for a longer background action and the simple past for a shorter action that interrupts it.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, false, 822, 3),
  ('27bae9be-1040-4f4f-819e-3c5cce962d9c', '97ad1353-0e59-48c5-be87-030c6052443e', 'Base and Derived Quantities in the SI System', 'Introduces the seven SI base quantities and their units, and shows how derived quantities such as area, density and force are built from them.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, true, 3982, 1),
  ('c75dcf77-eaf4-4f9b-bd18-8e26dc9bd3af', '97ad1353-0e59-48c5-be87-030c6052443e', 'Prefixes, Unit Conversion and Scientific Notation', 'Practises using prefixes such as kilo-, centi- and milli-, converting between units such as km/h and m/s, and writing very large or very small numbers in scientific notation.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, true, 3878, 2),
  ('1d9567dc-e2f9-4f57-80e9-443e9fc0041f', '97ad1353-0e59-48c5-be87-030c6052443e', 'Measurement Uncertainty and Significant Figures', 'Explains accuracy, precision and sources of error in measurement, and shows how to count and round to the correct number of significant figures.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, false, 2626, 3),
  ('0370c2c2-07bb-45ff-9e80-3919709522fc', '7017fa3e-1ce3-42d0-ba90-45ca5f36a7f7', 'Distance, Displacement, Speed and Velocity', 'Distinguishes the scalars distance and speed from the vectors displacement and velocity, and calculates average speed and average velocity for journeys along a straight road.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, false, 198, 1),
  ('e80d3e77-ad25-489a-b2f9-9a3637e37113', '7017fa3e-1ce3-42d0-ba90-45ca5f36a7f7', 'Acceleration and Velocity–Time Graphs', 'Defines acceleration as the rate of change of velocity and shows how to read acceleration from the slope and displacement from the area under a velocity–time graph.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, false, 138, 2),
  ('a04e4ea1-e3bd-4d15-948e-ecb8219870e6', '7017fa3e-1ce3-42d0-ba90-45ca5f36a7f7', 'Relative Velocity in One Dimension', 'Explains how to find the velocity of one object as seen from another when both move along the same straight line, in the same or opposite directions.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, false, 1555, 3),
  ('f1e6026f-fa4a-440a-83a8-820abf92ec53', '4e62812d-ceea-4d8c-8b34-a8ec9d61dc1d', 'Dalton''s Atomic Theory and Subatomic Particles', 'Traces the development of atomic theory from Dalton to the discovery of the electron, proton and neutron by Thomson, Rutherford and Chadwick.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, true, 3027, 1),
  ('c54d0424-c37d-4bba-8945-19e6e8789a41', '4e62812d-ceea-4d8c-8b34-a8ec9d61dc1d', 'Atomic Number, Mass Number and Isotopes', 'Explains how to find the numbers of protons, neutrons and electrons in atoms and ions, and how to calculate relative atomic mass from isotope abundances.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, true, 3599, 2),
  ('719722ee-7807-4a93-84d7-fe7cc86f307d', '4e62812d-ceea-4d8c-8b34-a8ec9d61dc1d', 'Bohr''s Model and Electron Configuration', 'Describes Bohr''s energy levels and the idea of sublevels, and shows how to write electron configurations for the first 20 elements.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, false, 4397, 3),
  ('3e6a8f1f-58f6-4bd5-9369-12da7a939121', '0f21d6ad-2f1c-4261-ba9b-392b0ab36398', 'From Döbereiner''s Triads to Mendeleev''s Periodic Table', 'Reviews early attempts to group elements with similar properties, from Döbereiner''s triads and Newlands'' octaves to Mendeleev''s table and its successful predictions.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, false, 371, 1),
  ('5b15b29e-426a-4017-98d8-8eac43861116', '0f21d6ad-2f1c-4261-ba9b-392b0ab36398', 'The Modern Periodic Law: Periods, Groups and Blocks', 'Explains why elements are arranged by increasing atomic number and how to locate an element''s period, group and block from its electron configuration.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, false, 4507, 2),
  ('46da2b4e-67f2-4765-8f55-53567633e9b5', '0f21d6ad-2f1c-4261-ba9b-392b0ab36398', 'Periodic Trends: Atomic Radius, Ionization Energy and Electronegativity', 'Shows how atomic size, ionization energy, electronegativity and metallic character change across a period and down a group, and explains why.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, false, 1350, 3),
  ('eac25124-3fba-46ce-83eb-93fb141c5dbf', 'cca7889c-2933-4637-9096-f283f0998457', 'Characteristics of Living Things', 'Covers the features shared by all living things, including nutrition, respiration, excretion, growth, reproduction, sensitivity and movement.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, true, 2279, 1),
  ('f13ca9a5-6470-4fa4-9047-05789d58337a', 'cca7889c-2933-4637-9096-f283f0998457', 'Taxonomic Hierarchy and Binomial Nomenclature', 'Explains the levels of classification from kingdom to species and the rules for writing scientific names, such as Eragrostis tef for teff.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, true, 222, 2),
  ('69349aae-a979-4089-ac15-621038433666', 'cca7889c-2933-4637-9096-f283f0998457', 'The Five-Kingdom System of Classification', 'Compares the main features of Monera, Protista, Fungi, Plantae and Animalia using familiar Ethiopian examples.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, false, 2790, 3),
  ('0f4f1115-d423-4b4e-9052-2a6033b55470', '1ff1284d-1afb-48c3-aa9c-ebeb041629c4', 'The Cell Theory and the Light Microscope', 'Introduces the cell theory and shows how to use a light microscope, prepare a simple slide of onion epidermis and calculate magnification.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, false, 650, 1),
  ('58058cbe-15ce-4f09-baa8-4ae53996e704', '1ff1284d-1afb-48c3-aa9c-ebeb041629c4', 'Cell Organelles and Their Functions', 'Describes the structure and function of the nucleus, mitochondria, ribosomes, chloroplasts, vacuoles and cell membrane, and compares plant and animal cells.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, false, 4877, 2),
  ('0f177264-a796-4530-b1ad-b9429f62efa8', '1ff1284d-1afb-48c3-aa9c-ebeb041629c4', 'Diffusion, Osmosis and Active Transport', 'Explains how substances move into and out of cells, and what happens to plant and animal cells placed in dilute and concentrated solutions.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, false, 1214, 3)
insert into public.questions (id, subject_id, chapter_id, stem, options, correct_option, explanation, difficulty, is_free, sort) values
  ('bc41fb40-ae3d-4987-887b-df05185d1639', 'feeae2e5-be79-4c92-8112-34f038503232', 'badca31f-e97e-4ff7-bdaf-072d8826cf8e', 'Which of the following sets is empty?', '[{"key":"A","text":"{x | x is a natural number and 3 < x < 4}"},{"key":"B","text":"{0}"},{"key":"C","text":"{x | x² = 9}"},{"key":"D","text":"{x | x is an even prime number}"}]'::jsonb, 'A', 'No natural number lies strictly between 3 and 4, so the first set has no elements. {0} contains the element 0, {x | x² = 9} = {−3, 3}, and the only even prime number is 2.', 1, true, 1),
  ('e7e2527c-228a-4c28-9822-5dae7ba1653e', 'feeae2e5-be79-4c92-8112-34f038503232', 'badca31f-e97e-4ff7-bdaf-072d8826cf8e', 'A set A has 5 elements. How many proper subsets does A have?', '[{"key":"A","text":"32"},{"key":"B","text":"31"},{"key":"C","text":"25"},{"key":"D","text":"10"}]'::jsonb, 'B', 'A set with n elements has 2ⁿ subsets, so A has 2⁵ = 32 subsets. Every subset except A itself is proper, giving 32 − 1 = 31 proper subsets.', 2, true, 2),
  ('7324269c-7946-47e6-b8a3-df3d17087e94', 'feeae2e5-be79-4c92-8112-34f038503232', 'badca31f-e97e-4ff7-bdaf-072d8826cf8e', 'Let U = {1, 2, 3, …, 10}, A = {2, 4, 6, 8, 10} and B = {1, 2, 3, 4, 5}. What is A ∩ B′?', '[{"key":"A","text":"{2, 4}"},{"key":"B","text":"{6, 7, 8, 9, 10}"},{"key":"C","text":"{1, 3, 5}"},{"key":"D","text":"{6, 8, 10}"}]'::jsonb, 'D', 'B′ = U − B = {6, 7, 8, 9, 10}. The elements of A that are also in B′ are 6, 8 and 10, so A ∩ B′ = {6, 8, 10}.', 2, true, 3),
  ('9f71cd47-4757-4222-afd6-e8ddcfc0259b', 'feeae2e5-be79-4c92-8112-34f038503232', 'badca31f-e97e-4ff7-bdaf-072d8826cf8e', 'In a class of 40 students in Hawassa, 24 play football, 19 play volleyball and 5 play neither sport. How many students play football only?', '[{"key":"A","text":"8"},{"key":"B","text":"16"},{"key":"C","text":"11"},{"key":"D","text":"19"}]'::jsonb, 'B', 'Students who play at least one sport: n(F ∪ V) = 40 − 5 = 35. Then n(F ∩ V) = 24 + 19 − 35 = 8, so football only = 24 − 8 = 16.', 3, true, 4),
  ('d41ff559-0b68-477a-ae0d-24673748a354', 'feeae2e5-be79-4c92-8112-34f038503232', '49196339-1a56-4778-9695-3837fbe86bc0', 'Which of the following numbers is irrational?', '[{"key":"A","text":"√49"},{"key":"B","text":"0.121212…"},{"key":"C","text":"22/7"},{"key":"D","text":"√20"}]'::jsonb, 'D', '√20 = 2√5 cannot be written as a ratio of two integers, so it is irrational. √49 = 7, 0.121212… = 12/99 and 22/7 are all rational.', 1, false, 1),
  ('5c17ad6b-d8ee-43f7-a70a-d6cec5e4a007', 'feeae2e5-be79-4c92-8112-34f038503232', '49196339-1a56-4778-9695-3837fbe86bc0', 'Express 0.363636… (the digits 36 repeat forever) as a fraction in its simplest form.', '[{"key":"A","text":"9/25"},{"key":"B","text":"4/11"},{"key":"C","text":"36/100"},{"key":"D","text":"6/11"}]'::jsonb, 'B', 'Let x = 0.3636…. Then 100x = 36.3636…, so 100x − x = 36, which gives 99x = 36 and x = 36/99 = 4/11.', 2, false, 2),
  ('f2bfb083-53e6-40c9-a910-59c4687f27e7', 'feeae2e5-be79-4c92-8112-34f038503232', '49196339-1a56-4778-9695-3837fbe86bc0', 'Two minibus taxis on different routes leave Meskel Square at 7:00 a.m. One returns to the square every 24 minutes and the other every 36 minutes. At what time will both next be at the square together?', '[{"key":"A","text":"7:36 a.m."},{"key":"B","text":"8:00 a.m."},{"key":"C","text":"8:12 a.m."},{"key":"D","text":"9:00 a.m."}]'::jsonb, 'C', 'We need the LCM of 24 and 36. Since 24 = 2³ × 3 and 36 = 2² × 3², LCM = 2³ × 3² = 72 minutes, and 72 minutes after 7:00 a.m. is 8:12 a.m.', 2, false, 3),
  ('93ca2f2b-2758-47c4-a6bc-cc3d354ff3c1', 'feeae2e5-be79-4c92-8112-34f038503232', '49196339-1a56-4778-9695-3837fbe86bc0', 'Rationalize the denominator and simplify: 2 ÷ (√5 − √3)', '[{"key":"A","text":"√5 + √3"},{"key":"B","text":"√5 − √3"},{"key":"C","text":"2(√5 + √3)"},{"key":"D","text":"(√5 + √3)/2"}]'::jsonb, 'A', 'Multiply the numerator and denominator by the conjugate √5 + √3: 2(√5 + √3) ÷ ((√5)² − (√3)²) = 2(√5 + √3) ÷ (5 − 3) = √5 + √3.', 3, false, 4),
  ('b825b40d-2265-4288-a0dd-4698c0bcc719', '732f358e-144f-4d14-8ee4-788895927acd', '5c109745-2e83-498a-84ba-0f70d0f62e75', 'Choose the correct question tag: “You live in Bole, _____?”', '[{"key":"A","text":"do you"},{"key":"B","text":"don''t you"},{"key":"C","text":"aren''t you"},{"key":"D","text":"isn''t it"}]'::jsonb, 'B', 'The statement is positive and uses the simple present with “you”, so the tag needs the negative auxiliary “don''t” and the same pronoun: “don''t you?”', 1, true, 1),
  ('69ba7975-47c3-42a2-b15f-b07277d973ad', '732f358e-144f-4d14-8ee4-788895927acd', '5c109745-2e83-498a-84ba-0f70d0f62e75', 'Choose the correct verb forms: “Most people in our neighbourhood _____ to work by minibus taxi, but this week many of them _____ because the main road is closed for repairs.”', '[{"key":"A","text":"go / are walking"},{"key":"B","text":"are going / walk"},{"key":"C","text":"goes / walks"},{"key":"D","text":"went / walking"}]'::jsonb, 'A', '“Go” is in the simple present because it describes a regular habit. “Are walking” is in the present continuous because it describes a temporary situation happening this week.', 2, true, 2),
  ('b888e092-4962-402f-9dc5-98fcb0db0a48', '732f358e-144f-4d14-8ee4-788895927acd', '5c109745-2e83-498a-84ba-0f70d0f62e75', 'Choose the phrasal verb that best completes the sentence: “The city administration plans to _____ the old, unsafe buildings and put up new apartment blocks in their place.”', '[{"key":"A","text":"pull down"},{"key":"B","text":"look after"},{"key":"C","text":"put off"},{"key":"D","text":"give up"}]'::jsonb, 'A', '“Pull down” means to demolish a building, which fits replacing old buildings with new ones. “Look after” means take care of, “put off” means postpone and “give up” means stop trying.', 2, true, 3),
  ('a1c4ba89-a391-4398-9144-401a336060df', '732f358e-144f-4d14-8ee4-788895927acd', '5c109745-2e83-498a-84ba-0f70d0f62e75', 'Read the passage and answer the question. “Every morning, thousands of people pour into the centre of Addis Ababa. Light-rail trains are packed, minibus taxis queue at every stop, and street vendors set up their stalls before the shops open. By evening, the flow reverses as workers head home to the fast-growing neighbourhoods on the edge of the city.” What can you infer from the passage?', '[{"key":"A","text":"Most workers live in the city centre."},{"key":"B","text":"Street vendors work only in the evening."},{"key":"C","text":"Light-rail trains do not run in the morning."},{"key":"D","text":"Many people who work in the centre live on the outskirts of the city."}]'::jsonb, 'D', 'People pour into the centre in the morning and head home to neighbourhoods “on the edge of the city” in the evening, so many workers must live on the outskirts. The other three options contradict details in the passage.', 3, true, 4),
  ('0cbb08a8-9d75-49e0-ad55-2bc38710a6de', '732f358e-144f-4d14-8ee4-788895927acd', '81a1c026-a8e1-4235-bcc2-0f38f15c5b66', 'Choose the word that correctly completes the collocation: “I always _____ my homework before I watch TV.”', '[{"key":"A","text":"make"},{"key":"B","text":"take"},{"key":"C","text":"do"},{"key":"D","text":"give"}]'::jsonb, 'C', 'In English we say “do homework”. “Make”, “take” and “give” do not combine with “my homework” in this meaning.', 1, false, 1),
  ('1a4895b8-46b7-43d5-b9a1-e7ba2bd29824', '732f358e-144f-4d14-8ee4-788895927acd', '81a1c026-a8e1-4235-bcc2-0f38f15c5b66', 'Choose the best connector: “Reading every day improves your vocabulary. _____, it helps you to write more fluently.”', '[{"key":"A","text":"However"},{"key":"B","text":"Although"},{"key":"C","text":"In addition"},{"key":"D","text":"Instead"}]'::jsonb, 'C', 'The second sentence adds another benefit of reading, so an addition marker such as “In addition” is needed. “However” and “Instead” signal contrast or replacement, and “Although” cannot begin a main clause like this.', 2, false, 2),
  ('67374dcd-9b40-4a3f-bbb6-72226645d0da', '732f358e-144f-4d14-8ee4-788895927acd', '81a1c026-a8e1-4235-bcc2-0f38f15c5b66', 'Choose the correct verb forms: “While I _____ for my biology test last night, the electricity suddenly _____ off.”', '[{"key":"A","text":"studied / was going"},{"key":"B","text":"am studying / goes"},{"key":"C","text":"had studied / was going"},{"key":"D","text":"was studying / went"}]'::jsonb, 'D', 'The longer background action takes the past continuous (“was studying”), and the short action that interrupted it takes the simple past (“went off”).', 2, false, 3),
  ('a58e7363-cdf7-42db-b691-1307c6fd22fa', '732f358e-144f-4d14-8ee4-788895927acd', '81a1c026-a8e1-4235-bcc2-0f38f15c5b66', 'Read the passage and answer the question. “Selam used to read all her notes the night before a test, but a week later she had forgotten most of them. This year she changed her approach. After every lesson she writes a short summary, and every Saturday she tests herself with questions from the textbook. Her results have improved, and she feels much calmer before exams.” Which statement is best supported by the passage?', '[{"key":"A","text":"Regular review and self-testing helped Selam remember more."},{"key":"B","text":"Selam now studies only on Saturdays."},{"key":"C","text":"Selam no longer takes notes in class."},{"key":"D","text":"Reading all your notes the night before a test is the best way to study."}]'::jsonb, 'A', 'Selam''s results improved after she began summarizing every lesson and testing herself each week. The passage does not say she studies only on Saturdays or has stopped taking notes, and it shows that last-minute reading did not work for her.', 3, false, 4),
  ('05c53f73-1d70-48d6-b7c6-515995e888f0', 'f1b27081-0907-4d82-9b8d-6938fed24692', '97ad1353-0e59-48c5-be87-030c6052443e', 'Which of the following is an SI base quantity?', '[{"key":"A","text":"Force"},{"key":"B","text":"Velocity"},{"key":"C","text":"Electric current"},{"key":"D","text":"Energy"}]'::jsonb, 'C', 'Electric current, measured in amperes (A), is one of the seven SI base quantities. Force, velocity and energy are derived quantities built from base quantities.', 1, true, 1),
  ('06546ac0-e762-4fe2-840f-d8d61da3068e', 'f1b27081-0907-4d82-9b8d-6938fed24692', '97ad1353-0e59-48c5-be87-030c6052443e', 'A minibus travels along a straight road at 72 km/h. What is its speed in m/s?', '[{"key":"A","text":"7.2 m/s"},{"key":"B","text":"20 m/s"},{"key":"C","text":"36 m/s"},{"key":"D","text":"259.2 m/s"}]'::jsonb, 'B', '72 km/h = (72 × 1000 m) ÷ (3600 s) = 72,000 m ÷ 3600 s = 20 m/s.', 1, true, 2),
  ('c5dc38e5-bf5f-4526-9120-33796501dddc', 'f1b27081-0907-4d82-9b8d-6938fed24692', '97ad1353-0e59-48c5-be87-030c6052443e', 'How many significant figures are there in the measurement 0.004050 kg?', '[{"key":"A","text":"7"},{"key":"B","text":"6"},{"key":"C","text":"3"},{"key":"D","text":"4"}]'::jsonb, 'D', 'Leading zeros only show the position of the decimal point, so they are not significant. The digits 4, 0 and 5 and the final trailing zero after the decimal point are significant, giving 4 significant figures.', 2, true, 3),
  ('c562051d-4ea0-4b8b-9e94-8a36394d4b36', 'f1b27081-0907-4d82-9b8d-6938fed24692', '97ad1353-0e59-48c5-be87-030c6052443e', 'A stone has a density of 2.5 g/cm³. What is its density in kg/m³?', '[{"key":"A","text":"0.0025 kg/m³"},{"key":"B","text":"2.5 kg/m³"},{"key":"C","text":"250 kg/m³"},{"key":"D","text":"2500 kg/m³"}]'::jsonb, 'D', '1 g = 10⁻³ kg and 1 cm³ = 10⁻⁶ m³, so 1 g/cm³ = 10⁻³ ÷ 10⁻⁶ = 1000 kg/m³. Therefore 2.5 g/cm³ = 2.5 × 1000 = 2500 kg/m³.', 3, true, 4),
  ('882e9c3c-6a86-492f-8af5-582a7c196a2d', 'f1b27081-0907-4d82-9b8d-6938fed24692', '7017fa3e-1ce3-42d0-ba90-45ca5f36a7f7', 'A student walks 400 m east and then 300 m west along a straight road. What is her displacement?', '[{"key":"A","text":"700 m east"},{"key":"B","text":"100 m west"},{"key":"C","text":"100 m east"},{"key":"D","text":"500 m east"}]'::jsonb, 'C', 'Taking east as positive, displacement = +400 m − 300 m = +100 m, which is 100 m east. The distance walked is 700 m, but displacement depends only on the starting and finishing points.', 1, false, 1),
  ('989315d8-1664-409e-828f-3bd688c99f1a', 'f1b27081-0907-4d82-9b8d-6938fed24692', '7017fa3e-1ce3-42d0-ba90-45ca5f36a7f7', 'A car starts from rest and reaches a velocity of 24 m/s in 8 s with uniform acceleration. What is its acceleration?', '[{"key":"A","text":"3 m/s²"},{"key":"B","text":"0.33 m/s²"},{"key":"C","text":"16 m/s²"},{"key":"D","text":"192 m/s²"}]'::jsonb, 'A', 'a = (v − u) ÷ t = (24 m/s − 0 m/s) ÷ 8 s = 3 m/s².', 1, false, 2),
  ('7d0d9402-fc1e-4729-9098-89da1555e601', 'f1b27081-0907-4d82-9b8d-6938fed24692', '7017fa3e-1ce3-42d0-ba90-45ca5f36a7f7', 'Two trucks approach each other on a straight road, one at 60 km/h and the other at 40 km/h. What is the speed of one truck relative to the other?', '[{"key":"A","text":"20 km/h"},{"key":"B","text":"50 km/h"},{"key":"C","text":"60 km/h"},{"key":"D","text":"100 km/h"}]'::jsonb, 'D', 'When two objects move towards each other, their relative speed is the sum of their speeds: 60 km/h + 40 km/h = 100 km/h.', 2, false, 3),
  ('2cb1763e-8a2b-407a-8fcb-fa3017173875', 'f1b27081-0907-4d82-9b8d-6938fed24692', '7017fa3e-1ce3-42d0-ba90-45ca5f36a7f7', 'A velocity–time graph shows a car''s velocity increasing uniformly from 10 m/s to 20 m/s in 5 s. How far does the car travel during these 5 s?', '[{"key":"A","text":"50 m"},{"key":"B","text":"75 m"},{"key":"C","text":"100 m"},{"key":"D","text":"150 m"}]'::jsonb, 'B', 'Displacement equals the area under the velocity–time graph, which here is a trapezium: ½ × (10 m/s + 20 m/s) × 5 s = 75 m.', 3, false, 4),
  ('fdf18fd5-f0ab-47c3-b267-e0e5129f1456', '67e9cfd6-8c32-4efc-bb62-668a17b1e45e', '4e62812d-ceea-4d8c-8b34-a8ec9d61dc1d', 'Which experiment showed that an atom has a small, dense, positively charged nucleus?', '[{"key":"A","text":"Thomson''s cathode-ray experiment"},{"key":"B","text":"Millikan''s oil-drop experiment"},{"key":"C","text":"Chadwick''s discovery of the neutron"},{"key":"D","text":"Rutherford''s gold-foil (alpha-particle scattering) experiment"}]'::jsonb, 'D', 'In Rutherford''s experiment most alpha particles passed straight through the gold foil, but a few were deflected through large angles. This showed that the positive charge and most of the mass of an atom are concentrated in a tiny nucleus.', 1, true, 1),
  ('af8fbe6f-a06d-4fb7-907f-ef8e7a27a745', '67e9cfd6-8c32-4efc-bb62-668a17b1e45e', '4e62812d-ceea-4d8c-8b34-a8ec9d61dc1d', 'Natural chlorine is 75% chlorine-35 and 25% chlorine-37. What is the relative atomic mass of chlorine?', '[{"key":"A","text":"35.0"},{"key":"B","text":"35.5"},{"key":"C","text":"36.0"},{"key":"D","text":"36.5"}]'::jsonb, 'B', 'Relative atomic mass = (75 × 35 + 25 × 37) ÷ 100 = (2625 + 925) ÷ 100 = 3550 ÷ 100 = 35.5.', 2, true, 2),
  ('6f6c0cfe-48d2-48e2-82f3-d2cf33e58434', '67e9cfd6-8c32-4efc-bb62-668a17b1e45e', '4e62812d-ceea-4d8c-8b34-a8ec9d61dc1d', 'What is the electron configuration of magnesium (atomic number 12)?', '[{"key":"A","text":"1s² 2s² 2p⁶ 3s²"},{"key":"B","text":"1s² 2s² 2p⁸"},{"key":"C","text":"1s² 2s² 2p⁶ 3p²"},{"key":"D","text":"1s² 2s² 2p⁴ 3s² 3p²"}]'::jsonb, 'A', 'Magnesium has 12 electrons. Filling sublevels in order of increasing energy gives 1s² (2), 2s² (4), 2p⁶ (10) and 3s² (12), so the configuration is 1s² 2s² 2p⁶ 3s², or 2, 8, 2 by shells.', 2, true, 3),
  ('29099001-e37a-4429-80d1-ad540032fb4f', '67e9cfd6-8c32-4efc-bb62-668a17b1e45e', '4e62812d-ceea-4d8c-8b34-a8ec9d61dc1d', 'An ion X²⁻ has 18 electrons and a mass number of 34. How many neutrons are in its nucleus?', '[{"key":"A","text":"16"},{"key":"B","text":"20"},{"key":"C","text":"18"},{"key":"D","text":"34"}]'::jsonb, 'C', 'X²⁻ has gained 2 electrons, so the neutral atom has 18 − 2 = 16 electrons and therefore 16 protons. Neutrons = mass number − protons = 34 − 16 = 18.', 3, true, 4),
  ('0bf26eae-384b-483c-ab87-669109e9284c', '67e9cfd6-8c32-4efc-bb62-668a17b1e45e', '0f21d6ad-2f1c-4261-ba9b-392b0ab36398', 'In the modern periodic table, elements are arranged in order of increasing:', '[{"key":"A","text":"atomic mass"},{"key":"B","text":"atomic number"},{"key":"C","text":"number of neutrons"},{"key":"D","text":"density"}]'::jsonb, 'B', 'The modern periodic law states that the properties of elements are periodic functions of their atomic numbers, so elements are arranged by increasing atomic number (number of protons).', 1, false, 1),
  ('419d52f6-a912-41f0-9517-02679a3b95da', '67e9cfd6-8c32-4efc-bb62-668a17b1e45e', '0f21d6ad-2f1c-4261-ba9b-392b0ab36398', 'An element has the electron configuration 2, 8, 7. In which period and group is it found?', '[{"key":"A","text":"Period 7, Group IIIA"},{"key":"B","text":"Period 2, Group VIIA"},{"key":"C","text":"Period 3, Group VA"},{"key":"D","text":"Period 3, Group VIIA"}]'::jsonb, 'D', 'Its electrons occupy three shells, so the element is in Period 3. It has 7 valence electrons, so it belongs to Group VIIA (Group 17). The element is chlorine.', 2, false, 2),
  ('79637ce5-54ba-4e16-8e9d-a92e3ed31b6c', '67e9cfd6-8c32-4efc-bb62-668a17b1e45e', '0f21d6ad-2f1c-4261-ba9b-392b0ab36398', 'Which of the following Period 3 elements has the largest atomic radius?', '[{"key":"A","text":"Na"},{"key":"B","text":"Mg"},{"key":"C","text":"Al"},{"key":"D","text":"Cl"}]'::jsonb, 'A', 'Across a period the nuclear charge increases while electrons are added to the same shell, so the electrons are pulled closer and atoms get smaller. Sodium, at the start of Period 3, therefore has the largest radius.', 2, false, 3),
  ('0c71072c-164e-47da-be6c-46a13c02e82b', '67e9cfd6-8c32-4efc-bb62-668a17b1e45e', '0f21d6ad-2f1c-4261-ba9b-392b0ab36398', 'Which of the following elements has the highest first ionization energy?', '[{"key":"A","text":"Na"},{"key":"B","text":"Mg"},{"key":"C","text":"Ne"},{"key":"D","text":"Ar"}]'::jsonb, 'C', 'Ionization energy increases across a period and decreases down a group. Neon has a full outer shell that is closer to the nucleus than argon''s, so removing an electron from neon needs more energy than from argon, magnesium or sodium.', 3, false, 4),
  ('6767792c-550b-478f-803e-c9cee37a6127', 'cb781d4f-6bd3-45df-b75e-f3516397293f', 'cca7889c-2933-4637-9096-f283f0998457', 'Which list shows the levels of classification in the correct order, from largest to smallest?', '[{"key":"A","text":"Kingdom, Phylum, Class, Order, Family, Genus, Species"},{"key":"B","text":"Kingdom, Class, Phylum, Order, Family, Species, Genus"},{"key":"C","text":"Phylum, Kingdom, Class, Family, Order, Genus, Species"},{"key":"D","text":"Kingdom, Phylum, Order, Class, Genus, Family, Species"}]'::jsonb, 'A', 'The taxonomic hierarchy from the largest group to the smallest is Kingdom → Phylum → Class → Order → Family → Genus → Species.', 1, true, 1),
  ('42eb6f39-874f-4745-a2a5-5460f33c0a38', 'cb781d4f-6bd3-45df-b75e-f3516397293f', 'cca7889c-2933-4637-9096-f283f0998457', 'Which of the following correctly writes the scientific name of teff?', '[{"key":"A","text":"eragrostis tef"},{"key":"B","text":"Eragrostis Tef"},{"key":"C","text":"Tef eragrostis"},{"key":"D","text":"Eragrostis tef"}]'::jsonb, 'D', 'In binomial nomenclature the genus name comes first and begins with a capital letter, and the species name follows in lower-case letters. The name is printed in italics or underlined when handwritten.', 1, true, 2),
  ('0018528e-657b-4706-822d-dcbe0c972003', 'cb781d4f-6bd3-45df-b75e-f3516397293f', 'cca7889c-2933-4637-9096-f283f0998457', 'Mushrooms are placed in kingdom Fungi rather than kingdom Plantae mainly because they:', '[{"key":"A","text":"are multicellular"},{"key":"B","text":"have cells with a nucleus"},{"key":"C","text":"lack chlorophyll and absorb food from their surroundings"},{"key":"D","text":"grow in soil"}]'::jsonb, 'C', 'Plants contain chlorophyll and make their own food by photosynthesis, but fungi have no chlorophyll and feed by absorbing nutrients from dead or living matter. Both groups can be multicellular, have nucleated cells and grow in soil.', 2, true, 3),
  ('d154532e-8ba9-4e84-b796-d1d268042256', 'cb781d4f-6bd3-45df-b75e-f3516397293f', 'cca7889c-2933-4637-9096-f283f0998457', 'Two organisms belong to the same order. Which of the following must they also share?', '[{"key":"A","text":"The same genus"},{"key":"B","text":"The same class"},{"key":"C","text":"The same family"},{"key":"D","text":"The same species"}]'::jsonb, 'B', 'Each level of classification lies inside the level above it, so organisms in the same order must also be in the same class, phylum and kingdom. They may still belong to different families, genera and species.', 3, true, 4),
  ('7aa34730-0012-4513-9da8-891e6e9997d9', 'cb781d4f-6bd3-45df-b75e-f3516397293f', '1ff1284d-1afb-48c3-aa9c-ebeb041629c4', 'Which organelle is the main site of aerobic respiration in a cell?', '[{"key":"A","text":"Ribosome"},{"key":"B","text":"Golgi apparatus"},{"key":"C","text":"Mitochondrion"},{"key":"D","text":"Vacuole"}]'::jsonb, 'C', 'Mitochondria carry out aerobic respiration, releasing energy from glucose as ATP. Ribosomes make proteins, the Golgi apparatus packages and transports substances, and vacuoles store water and other materials.', 1, false, 1),
  ('b6f02c70-f582-4f22-b183-209cbd8923f6', 'cb781d4f-6bd3-45df-b75e-f3516397293f', '1ff1284d-1afb-48c3-aa9c-ebeb041629c4', 'A student views onion cells using a 10× eyepiece lens and a 40× objective lens. What is the total magnification?', '[{"key":"A","text":"50×"},{"key":"B","text":"400×"},{"key":"C","text":"30×"},{"key":"D","text":"4000×"}]'::jsonb, 'B', 'Total magnification = eyepiece magnification × objective magnification = 10 × 40 = 400×.', 1, false, 2),
  ('2e2ba51f-8302-41b2-a3ae-25ef905fbd32', 'cb781d4f-6bd3-45df-b75e-f3516397293f', '1ff1284d-1afb-48c3-aa9c-ebeb041629c4', 'Which structure is found in plant cells but NOT in animal cells?', '[{"key":"A","text":"Cell wall"},{"key":"B","text":"Cell membrane"},{"key":"C","text":"Nucleus"},{"key":"D","text":"Mitochondrion"}]'::jsonb, 'A', 'Plant cells have a cellulose cell wall, as well as chloroplasts and a large central vacuole. Animal cells have a cell membrane, a nucleus and mitochondria, but no cell wall.', 2, false, 3),
  ('7974aa34-ebff-461d-950f-30fbcfc25b7f', 'cb781d4f-6bd3-45df-b75e-f3516397293f', '1ff1284d-1afb-48c3-aa9c-ebeb041629c4', 'A red blood cell is placed in distilled water. What is most likely to happen?', '[{"key":"A","text":"It shrinks because water moves out of it by osmosis."},{"key":"B","text":"It stays the same because the solution is isotonic."},{"key":"C","text":"It gains salt by active transport."},{"key":"D","text":"It swells and may burst because water moves into it by osmosis."}]'::jsonb, 'D', 'Distilled water is more dilute (hypotonic) than the cytoplasm of the red blood cell, so water enters the cell by osmosis. Animal cells have no cell wall to resist the pressure, so the cell swells and may burst.', 3, false, 4)
