  ('2e83a5f7-d4a2-4891-bd27-e79114d2b15c', 9, null, 'mock', 'Grade 9 Mock Test 1', 'Mixed questions from every subject, timed like the real exam.', null, null, 15, true, '2026-09-15', 1),
  ('7d0014fb-3987-4612-bac5-8d66d15aaca5', 9, null, 'mock', 'Grade 9 Mock Test 2', 'Mixed questions from every subject, timed like the real exam.', null, null, 15, false, '2026-10-01', 2),
