insert into public.videos (id, chapter_id, title, description, duration_seconds, thumbnail_url, source_url, notes_url, is_free, view_count, sort) values
  ('814298a3-2f95-45ca-bf44-2fc5cd5a37c9', '9c3c1773-74af-4c78-a61f-a707ae1b9c93', 'Relations, Domain and Range', 'Defines a relation as a set of ordered pairs, shows how to find its domain and range from lists, graphs and formulas, and introduces the inverse of a relation.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, true, 4486, 1),
  ('17955bb3-e9ed-4808-83f3-a2c6ef7f51a4', '9c3c1773-74af-4c78-a61f-a707ae1b9c93', 'Types of Functions: One-to-One and Onto', 'Uses arrow diagrams and the horizontal line test to classify functions as one-to-one, onto or both, and explains which functions have inverse functions.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, true, 1207, 2),
  ('29968184-0ef0-411c-8493-d7536d0cbfe1', '9c3c1773-74af-4c78-a61f-a707ae1b9c93', 'Composition and Inverse of Functions', 'Works through composing two functions and finding the domain of a composite function, then computes the inverse of a one-to-one function step by step.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, false, 1874, 3),
  ('1b15acab-dade-4f90-9d57-cf54a06245c7', '2ba4717f-6be1-4531-8fa5-f7738d9948dd', 'Types of Matrices and Equality of Matrices', 'Introduces the order of a matrix and special matrices such as row, column, square, diagonal, identity and zero matrices, and states when two matrices are equal.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, false, 4179, 1),
  ('59d259e4-ff7a-4e7c-b37e-fcac5fc08ecc', '2ba4717f-6be1-4531-8fa5-f7738d9948dd', 'Operations on Matrices', 'Covers matrix addition, scalar multiplication, the row-by-column rule for multiplying matrices and the transpose, with attention to when a product is defined.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, false, 4575, 2),
  ('734ffd71-7ecb-4c04-bb7e-72d4ef0b199d', '2ba4717f-6be1-4531-8fa5-f7738d9948dd', 'Solving Linear Systems by Gaussian Elimination', 'Uses elementary row operations to reduce an augmented matrix to row-echelon form and solve a system of three linear equations in three unknowns.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, false, 4042, 3),
  ('357c9551-fae7-41ac-9976-6e4f19e61683', 'c13ec1eb-e58e-4828-bc6d-a804ec71e97f', 'Listening for Gist and Details: Floods and Droughts', 'Practises listening for the main message and for specific details in a radio report on seasonal floods and drought in Ethiopia.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, true, 2589, 1),
  ('1dce3b72-4f41-4d86-acb9-540800a5a79f', 'c13ec1eb-e58e-4828-bc6d-a804ec71e97f', 'Guessing Word Meanings from Context', 'Shows how to use context clues such as definitions, examples and contrasts to work out unfamiliar words in texts about natural hazards.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, true, 811, 2),
  ('7ccd6ba3-ae3a-4edd-b978-1ac48a0efb57', 'c13ec1eb-e58e-4828-bc6d-a804ec71e97f', 'Punctuation: Commas, Semicolons and Colons', 'Reviews the correct use of commas, semicolons and colons, and shows how to avoid comma splices and run-on sentences.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, false, 2921, 3),
  ('c5d7cf96-cf16-45f8-af11-c4486906fa5f', 'cae2f7e8-d1f0-494a-aead-7be53c886e1c', 'Reading: Ancient Civilizations of Ethiopia', 'Develops skimming, scanning and summarizing skills using texts about the civilizations of Aksum, Lalibela and Gondar.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, false, 1476, 1),
  ('b4a25781-4baa-4ec4-8dc9-168929fa4515', 'cae2f7e8-d1f0-494a-aead-7be53c886e1c', 'Defining and Non-defining Relative Clauses', 'Explains when to use who, which, that, whose and where, and when commas are needed around a relative clause.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, false, 2487, 2),
  ('89e28198-fbd1-4641-b3c8-0efcfcf28fea', 'cae2f7e8-d1f0-494a-aead-7be53c886e1c', 'Reported Speech: Statements and Questions', 'Shows how tenses, pronouns, word order and time expressions change when statements and questions are reported.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, false, 3888, 3),
  ('0bb09866-18ab-48e6-8821-646127f50241', '0ce0941e-4cc4-4087-a2b8-938a46199f0d', 'Scalars, Vectors and Vector Representation', 'Distinguishes scalar and vector quantities and shows how vectors are represented by arrows, by components and with the unit vectors i and j.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, true, 170, 1),
  ('00b8a305-315c-4d62-bdf2-ddc6ccaf8732', '0ce0941e-4cc4-4087-a2b8-938a46199f0d', 'Vector Addition: Graphical and Component Methods', 'Uses the head-to-tail method and resolution into components to find the magnitude and direction of a resultant vector.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, true, 1906, 2),
  ('c19e946d-cacc-47ea-8e2f-e1287807a853', '0ce0941e-4cc4-4087-a2b8-938a46199f0d', 'The Scalar (Dot) Product', 'Defines the dot product, uses it to find the angle between two vectors, and links it to the work done by a force.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, false, 2552, 3),
  ('8b657875-d685-480d-9c74-5f8f9ff59f1e', '62d52e25-745e-4e67-be04-e7f1d8386249', 'Newton''s Laws of Motion and Free-Body Diagrams', 'Explains inertia, F = ma and action–reaction pairs, and shows how to draw free-body diagrams to solve force problems.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, false, 418, 1),
  ('9bf78ae1-618b-45d5-b5f4-dc8f8e7236c0', '62d52e25-745e-4e67-be04-e7f1d8386249', 'Friction', 'Distinguishes static and kinetic friction, defines the coefficient of friction and solves problems on horizontal surfaces and inclined planes.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, false, 2850, 2),
  ('5dfb041c-d96f-432d-8c37-d01c93e7a1ec', '62d52e25-745e-4e67-be04-e7f1d8386249', 'Work, Energy, Impulse and Momentum', 'Applies the work–energy theorem, conservation of mechanical energy and conservation of momentum to falling objects and collisions.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, false, 4412, 3),
  ('6052dd8a-61bb-4faa-b3ba-266faeafb282', '2146b5a9-7606-453c-9571-1bd599ec1035', 'From Dalton to Rutherford: Development of Atomic Models', 'Traces the main atomic models and the key experiments, such as the cathode ray tube and the gold foil experiment, that revealed the electron and the nucleus.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, true, 1547, 1),
  ('32d73685-74ab-4a8e-8270-8f5332910024', '2146b5a9-7606-453c-9571-1bd599ec1035', 'Quantum Numbers and Electron Configurations', 'Explains the four quantum numbers and the shapes of s, p and d orbitals, and writes electron configurations using the Aufbau principle, the Pauli exclusion principle and Hund''s rule.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, true, 3351, 2),
  ('895dae8e-374d-41c5-a040-1f3db9680699', '2146b5a9-7606-453c-9571-1bd599ec1035', 'Periodic Trends in Atomic Properties', 'Shows how atomic radius, ionization energy, electron affinity and electronegativity change across periods and down groups, and explains the main exceptions.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, false, 4825, 3),
  ('426f1ff7-8f7f-4920-849f-b8a9d1834c08', '38a31806-7b04-4ed9-9600-ef0b1eea03ab', 'Ionic, Covalent and Metallic Bonding', 'Compares how ionic, covalent and metallic bonds form, links bond type to electronegativity difference, and relates each type of bonding to the properties of substances.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, false, 1929, 1),
  ('9c68031c-cdaf-4d63-af82-0df1d99e6585', '38a31806-7b04-4ed9-9600-ef0b1eea03ab', 'Lewis Structures, Formal Charge and VSEPR Theory', 'Draws Lewis structures, calculates formal charges and uses VSEPR theory to predict molecular shapes such as linear, trigonal planar, tetrahedral, trigonal pyramidal and bent.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, false, 528, 2),
  ('e4fa8200-8765-4e63-a960-c1fc93326b13', '38a31806-7b04-4ed9-9600-ef0b1eea03ab', 'Hybridization and Intermolecular Forces', 'Explains sp, sp² and sp³ hybridization, and how London forces, dipole–dipole forces and hydrogen bonds affect boiling points.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, false, 4038, 3),
  ('9b53f5c8-708c-421d-95c1-9f917ad44812', '37f26a55-5cca-4fcf-87bd-22d05efd88f7', 'Enzymes as Biological Catalysts', 'Introduces enzymes as protein catalysts, describes their active sites, and explains how they lower the activation energy of reactions.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, true, 1075, 1),
  ('f9a31852-a913-48ed-bbd1-05f8dbd61624', '37f26a55-5cca-4fcf-87bd-22d05efd88f7', 'Models of Enzyme Action: Lock-and-Key and Induced Fit', 'Compares the lock-and-key and induced-fit models and explains how the enzyme–substrate complex forms and breaks down.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, true, 2712, 2),
  ('31926061-93ce-4f3c-8777-b4f6c09d9677', '37f26a55-5cca-4fcf-87bd-22d05efd88f7', 'Factors Affecting Enzyme Activity and Inhibition', 'Investigates the effects of temperature, pH and substrate concentration on reaction rate, and compares competitive and non-competitive inhibition.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, false, 4679, 3),
  ('a32444f4-6ace-49df-8e74-aa152523286b', '3ccf273b-4bfe-4d5b-aafe-bc60c35e8a09', 'Mendel''s Laws of Inheritance', 'Explains Mendel''s pea plant experiments, dominant and recessive alleles, and the laws of segregation and independent assortment.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, false, 3565, 1),
  ('8ea28484-24be-453b-9e77-28114c44546a', '3ccf273b-4bfe-4d5b-aafe-bc60c35e8a09', 'Monohybrid and Dihybrid Crosses', 'Uses Punnett squares to work through monohybrid, dihybrid and test crosses and to predict genotype and phenotype ratios.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, false, 3790, 2),
  ('396fb2cf-06cb-404f-9d54-1b8ff8bf7fd5', '3ccf273b-4bfe-4d5b-aafe-bc60c35e8a09', 'DNA, Genes and Chromosomes', 'Describes the double-helix structure of DNA and complementary base pairing, and explains how genes on chromosomes carry hereditary information.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, false, 2069, 3)
insert into public.questions (id, subject_id, chapter_id, stem, options, correct_option, explanation, difficulty, is_free, sort) values
  ('9a860e2b-6186-4817-aa79-25879714e507', '76ce77e9-5711-407d-bdfe-778c0d4c1113', '9c3c1773-74af-4c78-a61f-a707ae1b9c93', 'Which of the following functions from ℝ to ℝ is one-to-one?', '[{"key":"A","text":"f(x) = x²"},{"key":"B","text":"f(x) = |x|"},{"key":"C","text":"f(x) = cos x"},{"key":"D","text":"f(x) = x³ + 1"}]'::jsonb, 'D', 'f(x) = x³ + 1 is strictly increasing, so different inputs always give different outputs. The other three fail the horizontal line test: for example (−2)² = 2², |−1| = |1| and cos 0 = cos 2π.', 1, true, 1),
  ('16f5ab61-f421-4e9e-bbea-5ce63d3851ef', '76ce77e9-5711-407d-bdfe-778c0d4c1113', '9c3c1773-74af-4c78-a61f-a707ae1b9c93', 'If f(x) = 2x + 1 and g(x) = x², what is (f∘g)(3)?', '[{"key":"A","text":"49"},{"key":"B","text":"16"},{"key":"C","text":"19"},{"key":"D","text":"63"}]'::jsonb, 'C', '(f∘g)(3) = f(g(3)). First g(3) = 3² = 9, then f(9) = 2(9) + 1 = 19. Note that (g∘f)(3) = g(7) = 49 is a different value.', 2, true, 2),
  ('bb4469d6-5611-4a2b-b7d3-c36c248903df', '76ce77e9-5711-407d-bdfe-778c0d4c1113', '9c3c1773-74af-4c78-a61f-a707ae1b9c93', 'What is the inverse of the function f(x) = (3x − 2)/5?', '[{"key":"A","text":"f⁻¹(x) = (5x + 2)/3"},{"key":"B","text":"f⁻¹(x) = (5x − 2)/3"},{"key":"C","text":"f⁻¹(x) = (3x + 2)/5"},{"key":"D","text":"f⁻¹(x) = 5/(3x − 2)"}]'::jsonb, 'A', 'Write y = (3x − 2)/5 and solve for x: 5y = 3x − 2, so x = (5y + 2)/3. Interchanging x and y gives f⁻¹(x) = (5x + 2)/3.', 2, true, 3),
  ('fc35764d-a560-411a-bc1c-f8622ed36bb0', '76ce77e9-5711-407d-bdfe-778c0d4c1113', '9c3c1773-74af-4c78-a61f-a707ae1b9c93', 'If f(x) = 1/(x − 2) and g(x) = √x, what is the domain of f∘g?', '[{"key":"A","text":"x ≥ 0"},{"key":"B","text":"x ≥ 0 and x ≠ 4"},{"key":"C","text":"x ≠ 2"},{"key":"D","text":"x > 2"}]'::jsonb, 'B', '(f∘g)(x) = f(√x) = 1/(√x − 2). We need x ≥ 0 so that √x is defined, and √x ≠ 2, i.e. x ≠ 4, to avoid division by zero.', 3, true, 4),
  ('5e225114-c50a-421a-b493-0069b210d9cb', '76ce77e9-5711-407d-bdfe-778c0d4c1113', '2ba4717f-6be1-4531-8fa5-f7738d9948dd', 'If A is a 2 × 3 matrix and B is a 3 × 4 matrix, what is the order of the product AB?', '[{"key":"A","text":"2 × 4"},{"key":"B","text":"3 × 3"},{"key":"C","text":"4 × 2"},{"key":"D","text":"AB is not defined"}]'::jsonb, 'A', 'AB is defined because the number of columns of A (3) equals the number of rows of B (3). The product has the number of rows of A and the number of columns of B, so it is 2 × 4.', 1, false, 1),
  ('a61d9a33-c1c4-4660-81e6-c82e5e5715f0', '76ce77e9-5711-407d-bdfe-778c0d4c1113', '2ba4717f-6be1-4531-8fa5-f7738d9948dd', 'Let A = [1 2; 3 4] and B = [2 0; 1 −1], where a semicolon separates the rows. What is AB?', '[{"key":"A","text":"[2 4; −2 −2]"},{"key":"B","text":"[2 0; 3 −4]"},{"key":"C","text":"[4 −2; 10 −4]"},{"key":"D","text":"[3 2; 4 3]"}]'::jsonb, 'C', 'Multiply rows of A by columns of B: the first row is (1·2 + 2·1, 1·0 + 2·(−1)) = (4, −2) and the second row is (3·2 + 4·1, 3·0 + 4·(−1)) = (10, −4). So AB = [4 −2; 10 −4], which is different from BA = [2 4; −2 −2].', 2, false, 2),
  ('011b6a44-849b-497f-9d0f-1bf615ef8feb', '76ce77e9-5711-407d-bdfe-778c0d4c1113', '2ba4717f-6be1-4531-8fa5-f7738d9948dd', 'For matrices A and B such that the product AB is defined, the transpose (AB)ᵀ is always equal to:', '[{"key":"A","text":"AᵀBᵀ"},{"key":"B","text":"BA"},{"key":"C","text":"(BA)ᵀ"},{"key":"D","text":"BᵀAᵀ"}]'::jsonb, 'D', 'The transpose of a product is the product of the transposes in reverse order: (AB)ᵀ = BᵀAᵀ. In general AᵀBᵀ (which equals (BA)ᵀ) is different, and it may not even be defined when A and B are not square.', 2, false, 3),
  ('9e344790-cac0-463f-99f8-24c9623af143', '76ce77e9-5711-407d-bdfe-778c0d4c1113', '2ba4717f-6be1-4531-8fa5-f7738d9948dd', 'Solve the system x + y + z = 6, 2x − y + z = 3, x + 2y − z = 2 by Gaussian elimination. What is the solution (x, y, z)?', '[{"key":"A","text":"(2, 1, 3)"},{"key":"B","text":"(1, 2, 3)"},{"key":"C","text":"(3, 2, 1)"},{"key":"D","text":"(1, 3, 2)"}]'::jsonb, 'B', 'R₂ − 2R₁ gives −3y − z = −9 and R₃ − R₁ gives y − 2z = −4, so y = 2z − 4. Substituting: −3(2z − 4) − z = −9, so −7z = −21 and z = 3; then y = 2 and x = 6 − 2 − 3 = 1.', 3, false, 4),
  ('f329a5bb-5735-4b0f-8419-4a012829e1e9', '5f9222db-4916-48bc-9bf3-e7e100699e03', 'c13ec1eb-e58e-4828-bc6d-a804ec71e97f', 'Read the sentence: ''After weeks of heavy rain, the river overflowed and inundated the farms near the town.'' What does ''inundated'' mean in this sentence?', '[{"key":"A","text":"dried out"},{"key":"B","text":"flooded"},{"key":"C","text":"fenced"},{"key":"D","text":"fertilised"}]'::jsonb, 'B', 'The context of heavy rain and an overflowing river shows that water covered the farms, so ''inundated'' means flooded.', 1, true, 1),
  ('13fb7a36-491d-463d-bda6-c773577ac51f', '5f9222db-4916-48bc-9bf3-e7e100699e03', 'c13ec1eb-e58e-4828-bc6d-a804ec71e97f', 'Which sentence is punctuated correctly?', '[{"key":"A","text":"Deforestation causes soil erosion, it also destroys the habitats of many animals."},{"key":"B","text":"Deforestation causes soil erosion it also destroys the habitats of many animals."},{"key":"C","text":"Deforestation causes soil erosion; it also destroys the habitats of many animals."},{"key":"D","text":"Deforestation causes; soil erosion and it also destroys the habitats of many animals."}]'::jsonb, 'C', 'A semicolon correctly joins two closely related independent clauses. Joining them with only a comma creates a comma splice, joining them with no punctuation creates a run-on sentence, and a semicolon cannot separate a verb from its object.', 2, true, 2),
  ('e38cf26a-7f5c-49e0-a79f-509ac8e0e9bd', '5f9222db-4916-48bc-9bf3-e7e100699e03', 'c13ec1eb-e58e-4828-bc6d-a804ec71e97f', 'Read the passage and answer the question. ''Drought is often called a creeping hazard. Unlike an earthquake, which strikes in seconds, a drought develops slowly over months as the rains fail and wells dry up. By the time people recognise it, crops have already failed and livestock are dying.'' What is the main idea of the passage?', '[{"key":"A","text":"Drought develops gradually, so its damage is often recognised too late."},{"key":"B","text":"Earthquakes are more dangerous than droughts."},{"key":"C","text":"Wells dry up because people use too much water."},{"key":"D","text":"Livestock suffer more from earthquakes than from drought."}]'::jsonb, 'A', 'The passage contrasts the slow development of drought with sudden hazards and stresses that people notice it only after crops and livestock are already lost. The other options are either not stated or contradict the passage.', 2, true, 3),
  ('b4e11b4e-2c4b-48eb-ae87-6f270941ebc2', '5f9222db-4916-48bc-9bf3-e7e100699e03', 'c13ec1eb-e58e-4828-bc6d-a804ec71e97f', 'Read the passage and answer the question. ''Every rainy season, families in the lowland villages near the river move their grain stores onto raised wooden platforms and keep their goats on the hill behind the school. The elders say this practice began after the great flood that swept away their grandparents'' harvest.'' What can be inferred from the passage?', '[{"key":"A","text":"The villages have never experienced a serious flood."},{"key":"B","text":"The government forces the villagers to build platforms."},{"key":"C","text":"Goats are kept on the hill because they dislike wet grass."},{"key":"D","text":"Experience of a past flood taught the villagers to protect their food and animals."}]'::jsonb, 'D', 'The villagers take precautions every rainy season, and the elders link this habit to a past flood, so we can infer that experience taught them to protect their food and animals. The passage says nothing about government orders or goats disliking grass, and the great flood shows the area has flooded before.', 3, true, 4),
  ('b40250b7-bccd-4cd5-82e7-644a5e88629e', '5f9222db-4916-48bc-9bf3-e7e100699e03', 'cae2f7e8-d1f0-494a-aead-7be53c886e1c', 'Choose the correct word to complete the sentence: ''Lalibela is the town ______ the famous rock-hewn churches are found.''', '[{"key":"A","text":"which"},{"key":"B","text":"whose"},{"key":"C","text":"where"},{"key":"D","text":"who"}]'::jsonb, 'C', '''Where'' introduces a relative clause about a place and means ''in which''. ''Which'' would need a preposition (''in which''), ''whose'' shows possession and ''who'' refers to people.', 1, false, 1),
  ('f5c293e0-f4dd-482c-a8ca-f03ce73ccbc7', '5f9222db-4916-48bc-9bf3-e7e100699e03', 'cae2f7e8-d1f0-494a-aead-7be53c886e1c', 'Which sentence uses a non-defining relative clause correctly?', '[{"key":"A","text":"The Obelisk of Aksum, which was returned from Rome, now stands in its original city."},{"key":"B","text":"The Obelisk of Aksum which was returned from Rome now stands in its original city."},{"key":"C","text":"The Obelisk of Aksum, that was returned from Rome, now stands in its original city."},{"key":"D","text":"The Obelisk of Aksum, who was returned from Rome, now stands in its original city."}]'::jsonb, 'A', 'A non-defining relative clause adds extra information about a noun that is already identified, so it is separated by commas and uses ''which'' for things. ''That'' cannot introduce a non-defining clause, and ''who'' is used only for people.', 2, false, 2),
  ('29b5ff6c-0cad-4718-90f0-63d23afc96e6', '5f9222db-4916-48bc-9bf3-e7e100699e03', 'cae2f7e8-d1f0-494a-aead-7be53c886e1c', 'Choose the correct reported form of this question: Selam asked me, ''Have you ever visited Aksum?''', '[{"key":"A","text":"Selam asked me had I ever visited Aksum."},{"key":"B","text":"Selam asked me if had I ever visited Aksum."},{"key":"C","text":"Selam asked me if I have ever visited Aksum?"},{"key":"D","text":"Selam asked me if I had ever visited Aksum."}]'::jsonb, 'D', 'Reported yes/no questions use ''if'' or ''whether'', keep statement word order (subject before verb) and end with a full stop. The present perfect ''have visited'' also shifts back to the past perfect ''had visited''.', 3, false, 3),
  ('b1c04d24-d5f0-4efb-85f6-c60835f9745d', '5f9222db-4916-48bc-9bf3-e7e100699e03', 'cae2f7e8-d1f0-494a-aead-7be53c886e1c', 'Read the passage and answer the question. ''The Church of St George (Bete Giyorgis) in Lalibela was not built from stones placed one on top of another. Instead, workers cut downwards into solid rock, removing material until the cross-shaped church stood free in a deep pit.'' According to the passage, how was the church made?', '[{"key":"A","text":"By stacking cut stones on top of one another"},{"key":"B","text":"By carving it out of a single mass of solid rock"},{"key":"C","text":"By moving an older church from Aksum"},{"key":"D","text":"By building it on the foundations of a palace"}]'::jsonb, 'B', 'The passage says the church was not built from stacked stones; instead, workers cut down into solid rock until the church stood free. This means it was carved out of a single mass of rock.', 1, false, 4),
  ('89ba6e1c-d2d5-4420-a934-4a11f241d18c', 'e26fe376-65ab-4fe6-a801-6ceff372a288', '0ce0941e-4cc4-4087-a2b8-938a46199f0d', 'A student walks 3 km east and then 4 km north from her school in Bahir Dar. What is the magnitude of her displacement?', '[{"key":"A","text":"1 km"},{"key":"B","text":"5 km"},{"key":"C","text":"7 km"},{"key":"D","text":"25 km"}]'::jsonb, 'B', 'The two displacements are perpendicular, so the resultant is √(3² + 4²) = √25 = 5 km. The 7 km is the total distance walked, not the displacement.', 1, true, 1),
  ('04f4f885-3da6-4177-801a-fa512518245b', 'e26fe376-65ab-4fe6-a801-6ceff372a288', '0ce0941e-4cc4-4087-a2b8-938a46199f0d', 'A boy pulls a cart with a force of 20 N directed 30° above the horizontal. What are the horizontal and vertical components of the force?', '[{"key":"A","text":"Horizontal 10 N, vertical 17.3 N"},{"key":"B","text":"Horizontal 20 N, vertical 0 N"},{"key":"C","text":"Horizontal 14.1 N, vertical 14.1 N"},{"key":"D","text":"Horizontal 17.3 N, vertical 10 N"}]'::jsonb, 'D', 'Horizontal component = F cos 30° = 20 × 0.866 ≈ 17.3 N. Vertical component = F sin 30° = 20 × 0.5 = 10 N.', 2, true, 2),
  ('2020f5c5-d5ea-4c5c-a0b8-45587737a1ff', 'e26fe376-65ab-4fe6-a801-6ceff372a288', '0ce0941e-4cc4-4087-a2b8-938a46199f0d', 'Given the vectors A = 3i + 4j and B = 2i − j, what is the scalar product A · B?', '[{"key":"A","text":"2"},{"key":"B","text":"10"},{"key":"C","text":"−2"},{"key":"D","text":"6i − 4j"}]'::jsonb, 'A', 'Multiply matching components and add: A · B = (3)(2) + (4)(−1) = 6 − 4 = 2. The dot product is a scalar, so it cannot be a vector such as 6i − 4j.', 2, true, 3),
  ('87eb9751-7684-4204-90bf-1b8b3e423b99', 'e26fe376-65ab-4fe6-a801-6ceff372a288', '0ce0941e-4cc4-4087-a2b8-938a46199f0d', 'Vectors A and B have magnitudes of 6 units and 8 units. If the magnitude of A + B is 10 units, what is the angle between A and B?', '[{"key":"A","text":"0°"},{"key":"B","text":"60°"},{"key":"C","text":"90°"},{"key":"D","text":"180°"}]'::jsonb, 'C', '|A + B|² = A² + B² + 2AB cos θ, so 10² = 6² + 8² + 2(6)(8) cos θ. This gives 100 = 100 + 96 cos θ, so cos θ = 0 and θ = 90°.', 3, true, 4),
  ('07ea212a-36d0-47c6-a27a-eabf00f57ace', 'e26fe376-65ab-4fe6-a801-6ceff372a288', '62d52e25-745e-4e67-be04-e7f1d8386249', 'A net force of 12 N acts on a 3 kg box. What is the acceleration of the box?', '[{"key":"A","text":"36 m/s²"},{"key":"B","text":"15 m/s²"},{"key":"C","text":"0.25 m/s²"},{"key":"D","text":"4 m/s²"}]'::jsonb, 'D', 'From Newton''s second law, a = F/m = 12 N ÷ 3 kg = 4 m/s².', 1, false, 1),
  ('4fb0c756-f269-4dd9-98db-de07a5f1a657', 'e26fe376-65ab-4fe6-a801-6ceff372a288', '62d52e25-745e-4e67-be04-e7f1d8386249', 'A 10 kg crate is pushed across a horizontal floor at constant velocity. The coefficient of kinetic friction is 0.3. What horizontal force is being applied? (g = 10 m/s²)', '[{"key":"A","text":"30 N"},{"key":"B","text":"3 N"},{"key":"C","text":"100 N"},{"key":"D","text":"70 N"}]'::jsonb, 'A', 'At constant velocity the net force is zero, so the applied force equals kinetic friction: f = μₖN = μₖmg = 0.3 × 10 kg × 10 m/s² = 30 N.', 2, false, 2),
  ('4177e001-b5d7-4fb3-bc7d-fb6b819e8d87', 'e26fe376-65ab-4fe6-a801-6ceff372a288', '62d52e25-745e-4e67-be04-e7f1d8386249', 'A 2 kg trolley moving at 6 m/s collides with a stationary 4 kg trolley and they stick together. What is their common velocity just after the collision?', '[{"key":"A","text":"3 m/s"},{"key":"B","text":"6 m/s"},{"key":"C","text":"2 m/s"},{"key":"D","text":"4 m/s"}]'::jsonb, 'C', 'Momentum is conserved: (2 kg)(6 m/s) + (4 kg)(0) = (2 kg + 4 kg)v, so v = 12 ÷ 6 = 2 m/s.', 2, false, 3),
  ('bd7c23ac-0a24-44bb-a656-95dcc3f4f867', 'e26fe376-65ab-4fe6-a801-6ceff372a288', '62d52e25-745e-4e67-be04-e7f1d8386249', 'A 2 kg block starts from rest and slides down a frictionless ramp from a height of 5 m. It then moves onto a rough horizontal surface where μₖ = 0.25. How far does it slide on the rough surface before stopping? (g = 10 m/s²)', '[{"key":"A","text":"1.25 m"},{"key":"B","text":"20 m"},{"key":"C","text":"5 m"},{"key":"D","text":"40 m"}]'::jsonb, 'B', 'All the energy gained on the ramp is removed by friction on the rough surface: mgh = μₖmg × d. The mass cancels, so d = h/μₖ = 5 m ÷ 0.25 = 20 m.', 3, false, 4),
  ('812e7c02-d43d-48ac-9973-ae09f655e8eb', '15ef7eb9-95e2-49b0-802c-f21045d4c99f', '2146b5a9-7606-453c-9571-1bd599ec1035', 'How many neutrons are in an atom of chlorine-35? (Atomic number of Cl = 17)', '[{"key":"A","text":"17"},{"key":"B","text":"35"},{"key":"C","text":"18"},{"key":"D","text":"52"}]'::jsonb, 'C', 'Number of neutrons = mass number − atomic number = 35 − 17 = 18.', 1, true, 1),
  ('982a27ed-fac0-4fdc-b686-a897ac803e27', '15ef7eb9-95e2-49b0-802c-f21045d4c99f', '2146b5a9-7606-453c-9571-1bd599ec1035', 'What is the ground-state electron configuration of iron (Z = 26)?', '[{"key":"A","text":"1s² 2s² 2p⁶ 3s² 3p⁶ 3d⁸"},{"key":"B","text":"1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 4p⁶"},{"key":"C","text":"1s² 2s² 2p⁶ 3s² 3p⁶ 4s¹ 3d⁷"},{"key":"D","text":"1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 3d⁶"}]'::jsonb, 'D', 'Filling orbitals in Aufbau order (1s, 2s, 2p, 3s, 3p, 4s, 3d) with 26 electrons puts 18 in the argon core, 2 in 4s and the remaining 6 in 3d: [Ar] 4s² 3d⁶.', 2, true, 2),
  ('a3856148-e6f4-45ee-9e03-6c69f0dafcd6', '15ef7eb9-95e2-49b0-802c-f21045d4c99f', '2146b5a9-7606-453c-9571-1bd599ec1035', 'Which set of quantum numbers (n, l, mₗ, mₛ) is NOT allowed for an electron in an atom?', '[{"key":"A","text":"(2, 2, 1, +½)"},{"key":"B","text":"(2, 1, 0, +½)"},{"key":"C","text":"(3, 2, −2, −½)"},{"key":"D","text":"(4, 0, 0, −½)"}]'::jsonb, 'A', 'The azimuthal quantum number l can only take values from 0 to n − 1. For n = 2, l can be 0 or 1, so l = 2 is not allowed; the other sets all obey the rules.', 2, true, 3),
  ('83658a81-3b7b-4379-adb2-f7308cf33f6a', '15ef7eb9-95e2-49b0-802c-f21045d4c99f', '2146b5a9-7606-453c-9571-1bd599ec1035', 'Which of the following correctly ranks the first ionization energies of Mg, Al and Si?', '[{"key":"A","text":"Mg < Al < Si"},{"key":"B","text":"Al < Mg < Si"},{"key":"C","text":"Si < Al < Mg"},{"key":"D","text":"Al < Si < Mg"}]'::jsonb, 'B', 'Ionization energy generally increases across Period 3, but Al is lower than Mg because its outer electron is in a higher-energy 3p orbital shielded by the 3s electrons. The actual values are Al (578 kJ/mol) < Mg (738 kJ/mol) < Si (787 kJ/mol).', 3, true, 4),
  ('cb2c546c-7d6e-4b01-b0c1-ebbcf5db3add', '15ef7eb9-95e2-49b0-802c-f21045d4c99f', '38a31806-7b04-4ed9-9600-ef0b1eea03ab', 'Which of the following compounds contains ionic bonds?', '[{"key":"A","text":"NaCl"},{"key":"B","text":"CO₂"},{"key":"C","text":"CH₄"},{"key":"D","text":"H₂O"}]'::jsonb, 'A', 'NaCl forms from a metal and a non-metal with a large electronegativity difference, so electrons are transferred to form Na⁺ and Cl⁻ ions. CO₂, CH₄ and H₂O are covalent molecules made only of non-metals.', 1, false, 1),
  ('df9f1d80-2545-479a-91b4-0fad6214faf9', '15ef7eb9-95e2-49b0-802c-f21045d4c99f', '38a31806-7b04-4ed9-9600-ef0b1eea03ab', 'Using VSEPR theory, what is the molecular shape of ammonia (NH₃)?', '[{"key":"A","text":"Trigonal planar"},{"key":"B","text":"Trigonal pyramidal"},{"key":"C","text":"Tetrahedral"},{"key":"D","text":"Bent"}]'::jsonb, 'B', 'Nitrogen has three bonding pairs and one lone pair, giving four electron domains arranged tetrahedrally. The shape describes only the positions of the atoms, so NH₃ is trigonal pyramidal with bond angles of about 107°.', 2, false, 2),
  ('a1f72665-8b70-4c62-9eda-8a423f14353d', '15ef7eb9-95e2-49b0-802c-f21045d4c99f', '38a31806-7b04-4ed9-9600-ef0b1eea03ab', 'Water (H₂O) boils at 100 °C, while hydrogen sulfide (H₂S), which has a larger molar mass, boils at about −60 °C. What best explains this difference?', '[{"key":"A","text":"The O–H covalent bonds break when water boils"},{"key":"B","text":"H₂S molecules are non-polar"},{"key":"C","text":"London forces are stronger in water than in H₂S"},{"key":"D","text":"Water molecules are held together by hydrogen bonds"}]'::jsonb, 'D', 'Oxygen is small and highly electronegative, so water molecules form strong hydrogen bonds with each other that need much more energy to overcome. H₂S does not form significant hydrogen bonds, and London forces are actually stronger in the larger H₂S molecule; boiling separates molecules without breaking covalent bonds.', 2, false, 3),
  ('fed11f39-7668-4f4f-bd2a-6d1ee2f3c1bf', '15ef7eb9-95e2-49b0-802c-f21045d4c99f', '38a31806-7b04-4ed9-9600-ef0b1eea03ab', 'In the Lewis structure of carbon monoxide, C≡O, each atom has one lone pair. What are the formal charges on carbon and oxygen?', '[{"key":"A","text":"C: 0, O: 0"},{"key":"B","text":"C: +1, O: −1"},{"key":"C","text":"C: −1, O: +1"},{"key":"D","text":"C: −2, O: +2"}]'::jsonb, 'C', 'Formal charge = valence electrons − non-bonding electrons − ½(bonding electrons). For C: 4 − 2 − ½(6) = −1; for O: 6 − 2 − ½(6) = +1.', 3, false, 4),
  ('1b80cd6e-8c61-466e-b194-6c53588e0ef6', '4d23d01c-4602-43bc-b470-194dd5d1b3a7', '37f26a55-5cca-4fcf-87bd-22d05efd88f7', 'Salivary amylase begins digesting the starch in a mouthful of injera. Like all enzymes, it speeds up the reaction by:', '[{"key":"A","text":"increasing the activation energy"},{"key":"B","text":"lowering the activation energy"},{"key":"C","text":"raising the temperature of the mouth"},{"key":"D","text":"being used up in the reaction"}]'::jsonb, 'B', 'Enzymes provide an alternative reaction pathway with a lower activation energy, so more molecules can react at body temperature. They are not used up and do not raise the temperature.', 1, true, 1),
  ('f4f15472-8637-45ef-9494-4003289e7fb7', '4d23d01c-4602-43bc-b470-194dd5d1b3a7', '37f26a55-5cca-4fcf-87bd-22d05efd88f7', 'Pepsin works best in the stomach at about pH 2. What happens to its activity if it is placed in a solution of pH 8?', '[{"key":"A","text":"Its activity increases because more H⁺ ions are available"},{"key":"B","text":"Its activity stays the same because pH does not affect enzymes"},{"key":"C","text":"Its activity falls sharply because the active site changes shape"},{"key":"D","text":"It changes into a different enzyme that works at pH 8"}]'::jsonb, 'C', 'Each enzyme has an optimum pH. At pH 8, far from pepsin''s optimum, changes to ionic and hydrogen bonds alter the shape of the active site, so the substrate no longer fits well and activity falls sharply.', 2, true, 2),
  ('039c341f-cab0-41d3-a0d9-c270bbb4be16', '4d23d01c-4602-43bc-b470-194dd5d1b3a7', '37f26a55-5cca-4fcf-87bd-22d05efd88f7', 'In competitive inhibition, the inhibitor:', '[{"key":"A","text":"resembles the substrate and competes with it for the active site"},{"key":"B","text":"binds to a site other than the active site and changes the enzyme''s shape"},{"key":"C","text":"permanently destroys the enzyme by heating it"},{"key":"D","text":"increases the maximum rate of the reaction"}]'::jsonb, 'A', 'A competitive inhibitor has a shape similar to the substrate and occupies the active site, so its effect can be overcome by adding more substrate. Binding at another site and changing the enzyme''s shape describes non-competitive inhibition.', 2, true, 3),
  ('fa899c51-ddf9-44ac-a9d4-91c9bba140b2', '4d23d01c-4602-43bc-b470-194dd5d1b3a7', '37f26a55-5cca-4fcf-87bd-22d05efd88f7', 'In an experiment, the rate of an enzyme-catalysed reaction rises as substrate concentration increases, but then levels off even when more substrate is added. What is the best explanation?', '[{"key":"A","text":"The enzyme has been denatured by the substrate"},{"key":"B","text":"The substrate has started to act as an inhibitor"},{"key":"C","text":"The temperature of the mixture has dropped"},{"key":"D","text":"All active sites are occupied, so the enzyme is working at its maximum rate"}]'::jsonb, 'D', 'At high substrate concentration every active site is occupied (the enzyme is saturated), so extra substrate cannot raise the rate. The amount of enzyme has become the limiting factor.', 3, true, 4),
  ('2b10221e-d6b8-4123-854a-808fd5e11811', '4d23d01c-4602-43bc-b470-194dd5d1b3a7', '3ccf273b-4bfe-4d5b-aafe-bc60c35e8a09', 'In pea plants, tall (T) is dominant over short (t). If two heterozygous tall plants (Tt × Tt) are crossed, what fraction of the offspring is expected to be short?', '[{"key":"A","text":"1/2"},{"key":"B","text":"3/4"},{"key":"C","text":"1/4"},{"key":"D","text":"0"}]'::jsonb, 'C', 'Tt × Tt gives TT : Tt : tt in the ratio 1 : 2 : 1. Only tt plants are short, so 1/4 of the offspring are expected to be short.', 1, false, 1),
  ('b2290a66-ee99-4812-97bd-ed84a1182d31', '4d23d01c-4602-43bc-b470-194dd5d1b3a7', '3ccf273b-4bfe-4d5b-aafe-bc60c35e8a09', 'A sample of double-stranded DNA contains 30% adenine. What percentage of its bases is guanine?', '[{"key":"A","text":"20%"},{"key":"B","text":"30%"},{"key":"C","text":"40%"},{"key":"D","text":"70%"}]'::jsonb, 'A', 'By Chargaff''s rule A = T, so T is also 30% and A + T = 60%. The remaining 40% is shared equally by G and C, so G = 20%.', 2, false, 2),
  ('8cc60990-deda-4751-aaf0-62ce10d032cc', '4d23d01c-4602-43bc-b470-194dd5d1b3a7', '3ccf273b-4bfe-4d5b-aafe-bc60c35e8a09', 'In guinea pigs, black fur (B) is dominant over white fur (b). A black guinea pig is crossed with a white one, and about half of the offspring are white. What is the genotype of the black parent?', '[{"key":"A","text":"BB"},{"key":"B","text":"bb"},{"key":"C","text":"Cannot be determined"},{"key":"D","text":"Bb"}]'::jsonb, 'D', 'White offspring (bb) must receive a b allele from each parent, so the black parent must carry b and be Bb. The cross Bb × bb gives 1 black (Bb) : 1 white (bb), which matches the result.', 2, false, 3),
  ('8c364cfc-1a6d-4777-941e-dac508a33712', '4d23d01c-4602-43bc-b470-194dd5d1b3a7', '3ccf273b-4bfe-4d5b-aafe-bc60c35e8a09', 'In the cross AaBb × AaBb, where the two genes assort independently, what proportion of the offspring is expected to have the genotype AaBb?', '[{"key":"A","text":"1/16"},{"key":"B","text":"1/4"},{"key":"C","text":"9/16"},{"key":"D","text":"3/16"}]'::jsonb, 'B', 'Treat each gene separately: Aa × Aa gives Aa with probability 1/2, and Bb × Bb gives Bb with probability 1/2. So P(AaBb) = 1/2 × 1/2 = 1/4, i.e. 4 of the 16 boxes in the Punnett square.', 3, false, 4)
insert into public.tests (id, grade_id, subject_id, type, title, description, exam_year, year_label, duration_minutes, is_free, scheduled_for, sort) values
