insert into public.questions (id, subject_id, chapter_id, stem, options, correct_option, explanation, difficulty, is_free, sort) values
  ('2e6e1b4b-9e8b-4a0a-b2dd-e34790410639', '989f75a8-17b8-41df-9e3d-a993a59946cb', null, 'What is the value of lim (x→3) (x² − 9)/(x − 3)?', '[{"key":"A","text":"0"},{"key":"B","text":"3"},{"key":"C","text":"6"},{"key":"D","text":"The limit does not exist"}]'::jsonb, 'C', 'For x ≠ 3, (x² − 9)/(x − 3) = (x − 3)(x + 3)/(x − 3) = x + 3. Hence the limit is 3 + 3 = 6.', 1, false, 1),
  ('5a3d5cac-99ab-4b9b-be2e-96cedd4a87c4', '989f75a8-17b8-41df-9e3d-a993a59946cb', null, 'What is the local minimum value of the function f(x) = x³ − 6x² + 9x + 1?', '[{"key":"A","text":"5"},{"key":"B","text":"1"},{"key":"C","text":"−1"},{"key":"D","text":"3"}]'::jsonb, 'B', 'f′(x) = 3x² − 12x + 9 = 3(x − 1)(x − 3), so the critical points are x = 1 and x = 3. Since f″(x) = 6x − 12 and f″(3) = 6 > 0, the local minimum occurs at x = 3, where f(3) = 27 − 54 + 27 + 1 = 1.', 2, false, 2),
  ('8c6fdbf2-f95e-48e8-b913-ce348a8fbd38', '989f75a8-17b8-41df-9e3d-a993a59946cb', null, 'What is the value of the definite integral ∫₀² (3x² + 2x) dx?', '[{"key":"A","text":"12"},{"key":"B","text":"8"},{"key":"C","text":"10"},{"key":"D","text":"14"}]'::jsonb, 'A', 'An antiderivative of 3x² + 2x is x³ + x². Therefore ∫₀² (3x² + 2x) dx = (2³ + 2²) − (0 + 0) = 8 + 4 = 12.', 1, false, 3),
  ('ebb8d9ca-249a-473d-8e44-09def93f53ea', '989f75a8-17b8-41df-9e3d-a993a59946cb', null, 'What is the solution set of the equation log₂ x + log₂ (x − 2) = 3?', '[{"key":"A","text":"{−2, 4}"},{"key":"B","text":"{−2}"},{"key":"C","text":"{8}"},{"key":"D","text":"{4}"}]'::jsonb, 'D', 'log₂ x + log₂ (x − 2) = log₂ [x(x − 2)] = 3, so x² − 2x = 2³ = 8, i.e. (x − 4)(x + 2) = 0. The logarithms are defined only for x > 2, so x = 4 is the only solution.', 2, false, 4),
  ('8a457d10-5418-4139-b7e6-49b53dec8837', '989f75a8-17b8-41df-9e3d-a993a59946cb', null, 'The third term of a geometric sequence is 12 and its sixth term is 96. What is the first term of the sequence?', '[{"key":"A","text":"2"},{"key":"B","text":"4"},{"key":"C","text":"3"},{"key":"D","text":"6"}]'::jsonb, 'C', 'a₆/a₃ = r³ = 96/12 = 8, so r = 2. Then a₃ = a₁r² gives 12 = 4a₁, so a₁ = 3.', 2, false, 5),
  ('4e2ae990-d74e-48ce-8750-9ffecf3a074e', '989f75a8-17b8-41df-9e3d-a993a59946cb', null, 'If sin θ = 3/5 and θ lies in the second quadrant, what is the value of tan θ?', '[{"key":"A","text":"3/4"},{"key":"B","text":"−3/4"},{"key":"C","text":"−4/3"},{"key":"D","text":"4/3"}]'::jsonb, 'B', 'cos²θ = 1 − sin²θ = 1 − 9/25 = 16/25, and cosine is negative in the second quadrant, so cos θ = −4/5. Hence tan θ = sin θ/cos θ = (3/5)/(−4/5) = −3/4.', 1, false, 6),
  ('b1f53638-ee23-477e-9b91-e015562f4ddc', '989f75a8-17b8-41df-9e3d-a993a59946cb', null, 'For what value of k are the vectors a = (2, −1, 3) and b = (1, 4, k) perpendicular?', '[{"key":"A","text":"−2/3"},{"key":"B","text":"3/2"},{"key":"C","text":"2"},{"key":"D","text":"2/3"}]'::jsonb, 'D', 'Perpendicular vectors have a zero dot product: a · b = 2(1) + (−1)(4) + 3k = −2 + 3k = 0. Therefore k = 2/3.', 1, false, 7),
  ('42c20e7e-6b28-4f16-915f-3bb5e200ce6f', '989f75a8-17b8-41df-9e3d-a993a59946cb', null, 'A bag contains 5 red balls and 3 blue balls. Two balls are drawn at random, one after the other, without replacement. What is the probability that both balls are red?', '[{"key":"A","text":"25/64"},{"key":"B","text":"5/14"},{"key":"C","text":"5/8"},{"key":"D","text":"15/56"}]'::jsonb, 'B', 'P(first ball red) = 5/8 and, with one red ball removed, P(second ball red) = 4/7. So P(both red) = (5/8) × (4/7) = 20/56 = 5/14.', 2, false, 8),
  ('4b5f76a5-11eb-4f44-8615-5c1743407748', '989f75a8-17b8-41df-9e3d-a993a59946cb', null, 'What are the centre and the radius of the circle x² + y² − 6x + 4y − 12 = 0?', '[{"key":"A","text":"Centre (−3, 2), radius 5"},{"key":"B","text":"Centre (3, −2), radius 25"},{"key":"C","text":"Centre (3, −2), radius 5"},{"key":"D","text":"Centre (−3, 2), radius √12"}]'::jsonb, 'C', 'Completing the squares: (x² − 6x + 9) + (y² + 4y + 4) = 12 + 9 + 4, so (x − 3)² + (y + 2)² = 25. The centre is (3, −2) and the radius is √25 = 5.', 2, false, 9),
  ('fbd65819-d4a4-4233-b389-1db56b3b3e09', '989f75a8-17b8-41df-9e3d-a993a59946cb', null, 'What is the area of the region enclosed by the curves y = x² and y = 2x?', '[{"key":"A","text":"4/3 square units"},{"key":"B","text":"8/3 square units"},{"key":"C","text":"2 square units"},{"key":"D","text":"16/3 square units"}]'::jsonb, 'A', 'The curves meet where x² = 2x, i.e. at x = 0 and x = 2, and 2x ≥ x² between them. Area = ∫₀² (2x − x²) dx = [x² − x³/3] from 0 to 2 = 4 − 8/3 = 4/3 square units.', 3, false, 10),
  ('a38e8554-0c70-4248-b8de-167b011c19ca', '31c9b5cc-1575-4385-86cc-d18232834b11', null, 'Which one of the following gives the dimensions of power?', '[{"key":"A","text":"M L² T⁻²"},{"key":"B","text":"M L T⁻²"},{"key":"C","text":"M L² T⁻¹"},{"key":"D","text":"M L² T⁻³"}]'::jsonb, 'D', 'Power = work/time. Work = force × distance has dimensions (M L T⁻²)(L) = M L² T⁻², so power has dimensions M L² T⁻² ÷ T = M L² T⁻³.', 1, false, 1),
  ('053c3115-e886-43e1-ac4c-b9dd9f608d5d', '31c9b5cc-1575-4385-86cc-d18232834b11', null, 'A projectile is launched from level ground with a speed of 40 m/s at 30° above the horizontal. What is its horizontal range? (Take g = 10 m/s² and neglect air resistance.)', '[{"key":"A","text":"80 m"},{"key":"B","text":"80√3 m"},{"key":"C","text":"160 m"},{"key":"D","text":"40√3 m"}]'::jsonb, 'B', 'R = v² sin 2θ / g = (40)² × sin 60° / 10 = 160 × (√3/2) = 80√3 m ≈ 139 m.', 2, false, 2),
  ('8d349f75-e8fa-4c1c-8ae9-98ccfe922ed9', '31c9b5cc-1575-4385-86cc-d18232834b11', null, 'Two blocks of masses 2 kg and 3 kg are in contact on a frictionless horizontal surface. A horizontal force of 20 N is applied to the 2 kg block so that it pushes the 3 kg block. What force does the 2 kg block exert on the 3 kg block?', '[{"key":"A","text":"8 N"},{"key":"B","text":"20 N"},{"key":"C","text":"12 N"},{"key":"D","text":"4 N"}]'::jsonb, 'C', 'Both blocks have the same acceleration: a = F/(m₁ + m₂) = 20/5 = 4 m/s². The only horizontal force on the 3 kg block is the contact force, so F = ma = 3 × 4 = 12 N.', 2, false, 3),
  ('1160e2ad-7369-472e-9d32-4b8edca2c9e1', '31c9b5cc-1575-4385-86cc-d18232834b11', null, 'A 4 kg trolley moving at 6 m/s collides with a stationary 2 kg trolley, and the two stick together. How much kinetic energy is lost in the collision?', '[{"key":"A","text":"24 J"},{"key":"B","text":"48 J"},{"key":"C","text":"72 J"},{"key":"D","text":"0 J"}]'::jsonb, 'A', 'Momentum is conserved: 4 × 6 = (4 + 2)v, so v = 4 m/s. KE before = ½ × 4 × 6² = 72 J and KE after = ½ × 6 × 4² = 48 J, so 72 − 48 = 24 J is lost.', 2, false, 4),
  ('79fd1982-7915-446c-82d7-76bd761f250e', '31c9b5cc-1575-4385-86cc-d18232834b11', null, 'A 0.5 kg mass attached to a spring of force constant 200 N/m oscillates on a frictionless horizontal surface. What is the period of the oscillation?', '[{"key":"A","text":"0.05π s"},{"key":"B","text":"10π s"},{"key":"C","text":"0.1π s"},{"key":"D","text":"0.2π s"}]'::jsonb, 'C', 'T = 2π√(m/k) = 2π√(0.5/200) = 2π√0.0025 = 2π × 0.05 = 0.1π s ≈ 0.31 s.', 2, false, 5),
  ('63a6d056-4d00-4149-9ea1-22bae4b312d9', '31c9b5cc-1575-4385-86cc-d18232834b11', null, 'A fixed mass of an ideal gas at 27 °C is heated at constant pressure until its volume doubles. What is the final temperature of the gas?', '[{"key":"A","text":"54 °C"},{"key":"B","text":"600 °C"},{"key":"C","text":"150 °C"},{"key":"D","text":"327 °C"}]'::jsonb, 'D', 'At constant pressure V/T is constant, with T in kelvin. T₁ = 27 + 273 = 300 K, so doubling the volume gives T₂ = 600 K = 600 − 273 = 327 °C.', 2, false, 6),
  ('18d1fd40-7e9d-4b43-af91-48ed0de2d955', '31c9b5cc-1575-4385-86cc-d18232834b11', null, 'A 4 Ω resistor is connected in series with a parallel combination of a 6 Ω resistor and a 3 Ω resistor. The circuit is connected to a 12 V battery of negligible internal resistance. What is the current through the 6 Ω resistor?', '[{"key":"A","text":"2/3 A"},{"key":"B","text":"4/3 A"},{"key":"C","text":"2 A"},{"key":"D","text":"1 A"}]'::jsonb, 'A', 'The parallel pair has R = (6 × 3)/(6 + 3) = 2 Ω, so the total resistance is 4 + 2 = 6 Ω and the circuit current is 12/6 = 2 A. The voltage across the parallel pair is 2 A × 2 Ω = 4 V, so the current in the 6 Ω resistor is 4/6 = 2/3 A.', 3, false, 7),
  ('203870c2-cbfa-4ec7-b68a-ee5dea6b2533', '31c9b5cc-1575-4385-86cc-d18232834b11', null, 'The magnetic flux through each turn of a 200-turn coil decreases uniformly from 0.05 Wb to 0.01 Wb in 0.2 s. What is the magnitude of the average emf induced in the coil?', '[{"key":"A","text":"0.2 V"},{"key":"B","text":"4 V"},{"key":"C","text":"40 V"},{"key":"D","text":"400 V"}]'::jsonb, 'C', 'By Faraday''s law, ε = N ΔΦ/Δt = 200 × (0.05 − 0.01)/0.2 = 200 × 0.2 = 40 V.', 2, false, 8),
  ('d6873941-73a5-475d-a042-be2055594128', '31c9b5cc-1575-4385-86cc-d18232834b11', null, 'An object is placed 30 cm in front of a converging (convex) lens of focal length 10 cm. Where is the image formed, and what is its nature?', '[{"key":"A","text":"15 cm from the lens; virtual and upright"},{"key":"B","text":"15 cm from the lens; real and inverted"},{"key":"C","text":"7.5 cm from the lens; real and inverted"},{"key":"D","text":"30 cm from the lens; real and upright"}]'::jsonb, 'B', 'Using 1/f = 1/u + 1/v (real-is-positive): 1/v = 1/10 − 1/30 = 2/30, so v = +15 cm on the far side of the lens. A positive image distance means the image is real and inverted (and diminished, since m = 15/30 = 0.5).', 2, false, 9),
  ('4a55510f-a843-401f-ae9c-362f155d405c', '31c9b5cc-1575-4385-86cc-d18232834b11', null, 'Photons of energy 5.0 eV fall on a metal surface whose work function is 2.0 eV. What is the stopping potential for the emitted photoelectrons?', '[{"key":"A","text":"2.0 V"},{"key":"B","text":"5.0 V"},{"key":"C","text":"7.0 V"},{"key":"D","text":"3.0 V"}]'::jsonb, 'D', 'Einstein''s photoelectric equation gives KEmax = hf − φ = 5.0 eV − 2.0 eV = 3.0 eV. The stopping potential V₀ satisfies eV₀ = KEmax, so V₀ = 3.0 V.', 1, false, 10),
  ('8eb231f4-5d2b-4649-89a7-066cc2c43b26', '2f6ec046-2874-4405-8b1b-62ae239bbb77', null, 'Which organelle would you expect to be especially well developed in pancreatic cells that secrete large amounts of digestive enzymes?', '[{"key":"A","text":"Smooth endoplasmic reticulum"},{"key":"B","text":"Rough endoplasmic reticulum"},{"key":"C","text":"Lysosome"},{"key":"D","text":"Central vacuole"}]'::jsonb, 'B', 'Digestive enzymes are proteins, and proteins for export are made by ribosomes attached to the rough endoplasmic reticulum. Cells that secrete a lot of protein therefore have an extensive rough ER.', 2, false, 1),
  ('10684e83-9a92-47bd-9c4a-32c64b0db9b7', '2f6ec046-2874-4405-8b1b-62ae239bbb77', null, 'Which one of the following statements about enzymes is correct?', '[{"key":"A","text":"They are used up in the reactions they catalyse."},{"key":"B","text":"They shift the equilibrium position of a reversible reaction."},{"key":"C","text":"Their activity increases without limit as temperature rises."},{"key":"D","text":"They lower the activation energy of the reactions they catalyse."}]'::jsonb, 'D', 'Enzymes are biological catalysts: they speed up reactions by lowering the activation energy and are not consumed. They do not change the equilibrium position, and they are denatured at high temperatures, so activity falls above the optimum.', 1, false, 2),
  ('138d4c44-f906-4c65-b2a8-f25a6a68f582', '2f6ec046-2874-4405-8b1b-62ae239bbb77', null, 'During which stage does crossing over between non-sister chromatids of homologous chromosomes take place?', '[{"key":"A","text":"Prophase I of meiosis"},{"key":"B","text":"Metaphase II of meiosis"},{"key":"C","text":"Anaphase of mitosis"},{"key":"D","text":"Telophase II of meiosis"}]'::jsonb, 'A', 'In prophase I of meiosis, homologous chromosomes pair up (synapsis) and non-sister chromatids exchange segments at chiasmata. This crossing over produces new combinations of alleles.', 1, false, 3),
  ('a885fead-d100-4209-95c4-1b7102e42c0a', '2f6ec046-2874-4405-8b1b-62ae239bbb77', null, 'In pea plants, tall (T) is dominant over dwarf (t), and round seed (R) is dominant over wrinkled seed (r). If two plants with the genotype TtRr are crossed, what fraction of the offspring is expected to be tall with wrinkled seeds?', '[{"key":"A","text":"9/16"},{"key":"B","text":"1/16"},{"key":"C","text":"3/16"},{"key":"D","text":"1/4"}]'::jsonb, 'C', 'The two genes assort independently. From Tt × Tt, P(tall) = 3/4, and from Rr × Rr, P(wrinkled) = 1/4, so P(tall and wrinkled) = 3/4 × 1/4 = 3/16.', 2, false, 4),
  ('5fac8afe-a8b6-4966-aabd-ea25145a70cf', '2f6ec046-2874-4405-8b1b-62ae239bbb77', null, 'A segment of the template strand of a DNA molecule has the base sequence 3′-TAC GGA TTC-5′. What is the sequence of the mRNA transcribed from this segment?', '[{"key":"A","text":"5′-UAC GGA UUC-3′"},{"key":"B","text":"5′-ATG CCT AAG-3′"},{"key":"C","text":"5′-GAA UCC GUA-3′"},{"key":"D","text":"5′-AUG CCU AAG-3′"}]'::jsonb, 'D', 'mRNA is complementary and antiparallel to the template strand, and it contains uracil (U) instead of thymine to pair with adenine. So 3′-TAC GGA TTC-5′ is transcribed as 5′-AUG CCU AAG-3′.', 3, false, 5),
  ('61dd5495-fd19-419e-822a-f317ddf85af2', '2f6ec046-2874-4405-8b1b-62ae239bbb77', null, 'During photosynthesis, the oxygen gas released by green plants comes from which substance?', '[{"key":"A","text":"Carbon dioxide"},{"key":"B","text":"Water"},{"key":"C","text":"Glucose"},{"key":"D","text":"Ribulose bisphosphate (RuBP)"}]'::jsonb, 'B', 'In the light-dependent reactions, water is split (photolysis) to replace the electrons lost by chlorophyll: 2H₂O → 4H⁺ + 4e⁻ + O₂. The oxygen released therefore comes from water, not from CO₂.', 1, false, 6),
  ('ffcb74ca-1b1d-4064-9dcd-f146d4764f83', '2f6ec046-2874-4405-8b1b-62ae239bbb77', null, 'Antidiuretic hormone (ADH) increases the reabsorption of water in the kidney. On which part of the nephron does ADH mainly act?', '[{"key":"A","text":"Glomerulus"},{"key":"B","text":"Bowman''s capsule"},{"key":"C","text":"Collecting duct"},{"key":"D","text":"Proximal convoluted tubule"}]'::jsonb, 'C', 'ADH, released from the posterior pituitary, makes the walls of the collecting duct (and distal tubule) more permeable to water. More water is reabsorbed, so a smaller volume of more concentrated urine is produced.', 2, false, 7),
  ('2f72c5f1-d378-4621-88fb-38c38d3d41bc', '2f6ec046-2874-4405-8b1b-62ae239bbb77', null, 'In a grassland food chain, the producers fix 10,000 kJ of energy. If about 10% of the energy is passed from one trophic level to the next, how much energy reaches the tertiary consumers?', '[{"key":"A","text":"1,000 kJ"},{"key":"B","text":"100 kJ"},{"key":"C","text":"1 kJ"},{"key":"D","text":"10 kJ"}]'::jsonb, 'D', 'Producers → primary consumers → secondary consumers → tertiary consumers: 10,000 kJ → 1,000 kJ → 100 kJ → 10 kJ. Only about 10% of the energy is passed on at each step.', 2, false, 8),
  ('9519cb36-39c5-49ef-9ad1-8e0edfb11473', '2f6ec046-2874-4405-8b1b-62ae239bbb77', null, 'Which one of the following pairs are homologous structures?', '[{"key":"A","text":"The wing of a bird and the wing of a butterfly"},{"key":"B","text":"The wing of a bat and the arm of a human"},{"key":"C","text":"The fin of a shark and the flipper of a dolphin"},{"key":"D","text":"The eye of an octopus and the eye of a human"}]'::jsonb, 'B', 'Homologous structures share the same basic structure and evolutionary origin even if their functions differ; the bat wing and the human arm are both built on the pentadactyl limb plan. The other pairs are analogous structures, which have similar functions but evolved independently.', 2, false, 9),
  ('7750bdef-11ab-4c24-98cd-9651c0326219', '2f6ec046-2874-4405-8b1b-62ae239bbb77', null, 'A child is given a measles vaccine and later becomes immune to measles. What type of immunity is this?', '[{"key":"A","text":"Artificially acquired active immunity"},{"key":"B","text":"Naturally acquired active immunity"},{"key":"C","text":"Naturally acquired passive immunity"},{"key":"D","text":"Artificially acquired passive immunity"}]'::jsonb, 'A', 'The vaccine contains weakened or killed antigens, so the child''s own immune system makes antibodies and memory cells (active immunity). Because the antigen was given deliberately rather than by catching the disease, the immunity is artificially acquired.', 1, false, 10),
  ('11b9e939-2e8c-4410-980c-8d0749613d78', '989f75a8-17b8-41df-9e3d-a993a59946cb', null, 'What is the solution set of the inequality |2x − 3| < 5?', '[{"key":"A","text":"{x : x < −1 or x > 4}"},{"key":"B","text":"{x : −4 < x < 1}"},{"key":"C","text":"{x : −1 < x < 4}"},{"key":"D","text":"{x : 1 < x < 4}"}]'::jsonb, 'C', '|2x − 3| < 5 means −5 < 2x − 3 < 5. Adding 3 gives −2 < 2x < 8, and dividing by 2 gives −1 < x < 4.', 1, false, 1),
  ('56463c6d-dd3a-4329-af92-81bd32a20c74', '989f75a8-17b8-41df-9e3d-a993a59946cb', null, 'What is the solution of the equation 4ˣ⁺¹ = 8ˣ⁻¹?', '[{"key":"A","text":"x = −5"},{"key":"B","text":"x = 5"},{"key":"C","text":"x = 1"},{"key":"D","text":"x = 7"}]'::jsonb, 'B', 'Write both sides as powers of 2: 4ˣ⁺¹ = (2²)ˣ⁺¹ = 2²ˣ⁺² and 8ˣ⁻¹ = (2³)ˣ⁻¹ = 2³ˣ⁻³. Equating the exponents, 2x + 2 = 3x − 3, so x = 5.', 1, false, 2),
  ('d3564bd4-5e19-48ff-8322-57a3f3ede655', '989f75a8-17b8-41df-9e3d-a993a59946cb', null, 'When the polynomial p(x) = x³ − 2x² + kx + 6 is divided by (x − 2), the remainder is 10. What is the value of k?', '[{"key":"A","text":"2"},{"key":"B","text":"−2"},{"key":"C","text":"1"},{"key":"D","text":"4"}]'::jsonb, 'A', 'By the Remainder Theorem, the remainder is p(2) = 8 − 8 + 2k + 6 = 2k + 6. Setting 2k + 6 = 10 gives k = 2.', 1, false, 3),
  ('025a7932-9a1f-4c91-b6be-b27f6aca7c2d', '989f75a8-17b8-41df-9e3d-a993a59946cb', null, 'For what value of k does the system of equations 2x + 3y = 5 and 4x + ky = 7 have no solution?', '[{"key":"A","text":"3"},{"key":"B","text":"−6"},{"key":"C","text":"12"},{"key":"D","text":"6"}]'::jsonb, 'D', 'The system has no unique solution when the determinant of the coefficients is zero: 2k − 3(4) = 0, so k = 6. With k = 6 the equations become 4x + 6y = 10 and 4x + 6y = 7, which contradict each other, so there is no solution.', 2, false, 4),
  ('56a7c35f-69a9-4aa7-881d-762c9aecc641', '989f75a8-17b8-41df-9e3d-a993a59946cb', null, 'If z = 1 + i, where i² = −1, what is the value of z⁸?', '[{"key":"A","text":"16i"},{"key":"B","text":"−16"},{"key":"C","text":"16"},{"key":"D","text":"8"}]'::jsonb, 'C', 'z² = (1 + i)² = 1 + 2i + i² = 2i. Then z⁴ = (2i)² = −4 and z⁸ = (−4)² = 16.', 2, false, 5),
  ('dd59f497-530a-473c-b889-a08a9a0a0070', '989f75a8-17b8-41df-9e3d-a993a59946cb', null, 'How many terms of the arithmetic sequence 3, 7, 11, 15, … must be added to give a sum of 820?', '[{"key":"A","text":"18"},{"key":"B","text":"20"},{"key":"C","text":"22"},{"key":"D","text":"41"}]'::jsonb, 'B', 'Here a = 3 and d = 4, so Sₙ = (n/2)[2(3) + (n − 1)(4)] = n(2n + 1). Setting n(2n + 1) = 820 gives 2n² + n − 820 = 0, i.e. (n − 20)(2n + 41) = 0, so n = 20.', 3, false, 6),
  ('c629ea4f-3c25-4ab2-9600-d48b3ec6668b', '989f75a8-17b8-41df-9e3d-a993a59946cb', null, 'A committee of 3 people is to be chosen from 5 men and 4 women. In how many ways can the committee be formed if it must contain exactly 2 women?', '[{"key":"A","text":"60"},{"key":"B","text":"84"},{"key":"C","text":"20"},{"key":"D","text":"30"}]'::jsonb, 'D', 'Choose 2 of the 4 women in C(4, 2) = 6 ways and 1 of the 5 men in C(5, 1) = 5 ways. By the multiplication principle there are 6 × 5 = 30 possible committees.', 2, false, 7),
  ('b13cabb0-82ad-4ad0-a5b1-d63ddcd1937d', '989f75a8-17b8-41df-9e3d-a993a59946cb', null, 'What is the variance of the data set 2, 4, 6, 8, 10?', '[{"key":"A","text":"8"},{"key":"B","text":"4"},{"key":"C","text":"6"},{"key":"D","text":"2√2"}]'::jsonb, 'A', 'The mean is 30/5 = 6, and the squared deviations from the mean are 16, 4, 0, 4 and 16, which add up to 40. The variance is 40/5 = 8 (the standard deviation would be √8 = 2√2).', 2, false, 8),
  ('fe96a518-4bb2-44fb-b21b-e600ae59a81a', '989f75a8-17b8-41df-9e3d-a993a59946cb', null, 'A function is defined by f(x) = x² + k for x < 1 and f(x) = 3x − 1 for x ≥ 1. For what value of k is f continuous at x = 1?', '[{"key":"A","text":"0"},{"key":"B","text":"1"},{"key":"C","text":"2"},{"key":"D","text":"3"}]'::jsonb, 'B', 'For continuity at x = 1, the left-hand limit must equal f(1): lim (x→1⁻) (x² + k) = 1 + k and f(1) = 3(1) − 1 = 2. So 1 + k = 2, which gives k = 1.', 2, false, 9),
  ('220f44a3-8509-4a25-9f91-968d365998d6', '989f75a8-17b8-41df-9e3d-a993a59946cb', null, 'What is the equation of the tangent line to the curve y = x² − 3x at the point where x = 1?', '[{"key":"A","text":"y = x − 3"},{"key":"B","text":"y = −x + 1"},{"key":"C","text":"y = −x − 1"},{"key":"D","text":"y = −2x"}]'::jsonb, 'C', 'At x = 1, y = 1 − 3 = −2, and the slope is dy/dx = 2x − 3 = 2(1) − 3 = −1. The tangent line is y − (−2) = −1(x − 1), i.e. y = −x − 1.', 2, false, 10),
  ('bbf5bb87-ce7f-45c7-ad09-4567a5565f55', '15d0f3e0-4a95-4428-b43e-c49216775d7f', null, 'How many protons, neutrons and electrons are present in the ion ⁵⁶Fe³⁺? (Atomic number of Fe = 26)', '[{"key":"A","text":"26 protons, 30 neutrons, 29 electrons"},{"key":"B","text":"26 protons, 30 neutrons, 23 electrons"},{"key":"C","text":"23 protons, 30 neutrons, 26 electrons"},{"key":"D","text":"26 protons, 56 neutrons, 23 electrons"}]'::jsonb, 'B', 'The atomic number gives 26 protons, and neutrons = mass number − atomic number = 56 − 26 = 30. A 3+ ion has lost 3 electrons, so it has 26 − 3 = 23 electrons.', 1, false, 1),
  ('71efa119-660c-4285-907c-597b94eb242c', '15d0f3e0-4a95-4428-b43e-c49216775d7f', null, 'What is the ground-state electron configuration of chromium (Z = 24)?', '[{"key":"A","text":"[Ar] 3d⁴ 4s²"},{"key":"B","text":"[Ar] 3d⁶"},{"key":"C","text":"[Ar] 3d⁵ 4s¹"},{"key":"D","text":"[Ar] 4s² 4p⁴"}]'::jsonb, 'C', 'Chromium is an exception to the simple filling order because a half-filled 3d subshell is especially stable, so one 4s electron moves into 3d. Its configuration is therefore [Ar] 3d⁵ 4s¹ rather than [Ar] 3d⁴ 4s².', 2, false, 2),
  ('714ce34f-c54b-42ea-b990-e4db36d0d6d3', '15d0f3e0-4a95-4428-b43e-c49216775d7f', null, 'Which one of the following molecules is nonpolar even though it contains polar covalent bonds?', '[{"key":"A","text":"H₂O"},{"key":"B","text":"NH₃"},{"key":"C","text":"HCl"},{"key":"D","text":"CCl₄"}]'::jsonb, 'D', 'Each C–Cl bond in CCl₄ is polar, but the four bonds point symmetrically to the corners of a tetrahedron, so the bond dipoles cancel and there is no net dipole moment. H₂O (bent), NH₃ (trigonal pyramidal) and HCl all have a net dipole.', 2, false, 3),
  ('f6e8549e-105f-4cff-9ce5-155364da20cd', '15d0f3e0-4a95-4428-b43e-c49216775d7f', null, 'Methane burns according to the equation CH₄ + 2O₂ → CO₂ + 2H₂O. What mass of CO₂ is formed when 8.0 g of CH₄ reacts with 16.0 g of O₂? (C = 12, H = 1, O = 16)', '[{"key":"A","text":"11 g"},{"key":"B","text":"22 g"},{"key":"C","text":"44 g"},{"key":"D","text":"5.5 g"}]'::jsonb, 'A', 'n(CH₄) = 8.0/16 = 0.50 mol and n(O₂) = 16.0/32 = 0.50 mol; since 0.50 mol CH₄ would need 1.0 mol O₂, oxygen is the limiting reactant. From the 2 : 1 ratio of O₂ to CO₂, 0.50 mol O₂ gives 0.25 mol CO₂ = 0.25 × 44 = 11 g.', 3, false, 4),
  ('558f0f3a-d58a-4025-9d63-756571cc4d8f', '15d0f3e0-4a95-4428-b43e-c49216775d7f', null, 'A sample of gas occupies 2.0 L at 1.0 atm and 27 °C. What volume will it occupy at 2.0 atm and 327 °C?', '[{"key":"A","text":"1.0 L"},{"key":"B","text":"4.0 L"},{"key":"C","text":"8.0 L"},{"key":"D","text":"2.0 L"}]'::jsonb, 'D', 'Use P₁V₁/T₁ = P₂V₂/T₂ with temperatures in kelvin (300 K and 600 K): V₂ = 2.0 L × (1.0/2.0) × (600/300) = 2.0 L. Doubling the pressure halves the volume, but doubling the absolute temperature doubles it again.', 2, false, 5),
  ('c78d17c8-354c-4f34-ace5-50c6fd31cf38', '15d0f3e0-4a95-4428-b43e-c49216775d7f', null, 'What is the pH of a 0.010 M NaOH solution at 25 °C?', '[{"key":"A","text":"2"},{"key":"B","text":"12"},{"key":"C","text":"10"},{"key":"D","text":"7"}]'::jsonb, 'B', 'NaOH is a strong base, so [OH⁻] = 0.010 M = 1.0 × 10⁻² M and pOH = 2. At 25 °C, pH = 14 − pOH = 14 − 2 = 12.', 2, false, 6),
  ('7a67fe2c-6739-46b5-adff-f1ac3871c3e9', '15d0f3e0-4a95-4428-b43e-c49216775d7f', null, 'The rate law for a reaction is rate = k[A]²[B]. If the concentration of A is doubled and the concentration of B is halved, what happens to the rate of the reaction?', '[{"key":"A","text":"It stays the same."},{"key":"B","text":"It is halved."},{"key":"C","text":"It doubles."},{"key":"D","text":"It increases four times."}]'::jsonb, 'C', 'New rate = k(2[A])²(½[B]) = 4 × ½ × k[A]²[B] = 2 × the original rate. So the rate doubles.', 2, false, 7),
  ('f9bfc445-8436-4dc2-a60f-f694832e1904', '15d0f3e0-4a95-4428-b43e-c49216775d7f', null, 'For the equilibrium N₂(g) + 3H₂(g) ⇌ 2NH₃(g), ΔH = −92 kJ, which one of the following changes shifts the equilibrium position to the right?', '[{"key":"A","text":"Removing NH₃ from the mixture as it forms"},{"key":"B","text":"Increasing the temperature"},{"key":"C","text":"Decreasing the total pressure"},{"key":"D","text":"Adding an iron catalyst"}]'::jsonb, 'A', 'By Le Chatelier''s principle, removing a product makes the system form more NH₃, shifting the equilibrium to the right. Raising the temperature favours the endothermic reverse reaction, lowering the pressure favours the side with more moles of gas (the left), and a catalyst does not shift the equilibrium at all.', 2, false, 8),
  ('323ef44b-5fa0-4d72-a395-0754dab07106', '15d0f3e0-4a95-4428-b43e-c49216775d7f', null, 'Given the standard reduction potentials E°(Zn²⁺/Zn) = −0.76 V and E°(Cu²⁺/Cu) = +0.34 V, what is the standard emf of the galvanic cell Zn | Zn²⁺ || Cu²⁺ | Cu?', '[{"key":"A","text":"0.42 V"},{"key":"B","text":"−1.10 V"},{"key":"C","text":"1.10 V"},{"key":"D","text":"−0.42 V"}]'::jsonb, 'C', 'Copper, with the higher reduction potential, is the cathode and zinc is the anode. E°cell = E°(cathode) − E°(anode) = 0.34 − (−0.76) = +1.10 V.', 2, false, 9),
  ('e9c6af0e-3a60-4d15-bf7d-f89b1515ca48', '15d0f3e0-4a95-4428-b43e-c49216775d7f', null, 'Ethanoic acid is warmed with ethanol in the presence of a few drops of concentrated H₂SO₄. What is the main organic product?', '[{"key":"A","text":"Ethyl ethanoate"},{"key":"B","text":"Diethyl ether"},{"key":"C","text":"Ethanal"},{"key":"D","text":"Ethene"}]'::jsonb, 'A', 'A carboxylic acid and an alcohol undergo esterification, with concentrated H₂SO₄ as the catalyst: CH₃COOH + C₂H₅OH ⇌ CH₃COOC₂H₅ + H₂O. The ester formed is ethyl ethanoate (ethyl acetate).', 1, false, 10),
  ('0fe3e259-e640-4d35-bc7a-eec1fc38673d', '0c0dab0e-9f8c-42bb-8ebb-a8ec577f81ea', null, 'Choose the option that best completes the sentence: By the time we arrived at the station, the train ______.', '[{"key":"A","text":"has left"},{"key":"B","text":"had left"},{"key":"C","text":"leaves"},{"key":"D","text":"will have left"}]'::jsonb, 'B', 'The train left before another past action (our arrival), so the past perfect ''had left'' is needed. ''By the time'' followed by the simple past is normally completed with the past perfect.', 1, false, 1),
  ('06dbc104-0c05-4345-9fa0-4aabd91af19d', '0c0dab0e-9f8c-42bb-8ebb-a8ec577f81ea', null, 'Choose the option that best completes the sentence: If I ______ enough money last year, I would have bought a laptop.', '[{"key":"A","text":"saved"},{"key":"B","text":"have saved"},{"key":"C","text":"would save"},{"key":"D","text":"had saved"}]'::jsonb, 'D', 'This is a third conditional about an unreal past situation: if + past perfect, would have + past participle. So the correct form is ''had saved''.', 2, false, 2),
  ('9f98853d-9027-4bb1-b670-d689c2fb2141', '0c0dab0e-9f8c-42bb-8ebb-a8ec577f81ea', null, 'Choose the correct passive form of the sentence: “The workers are building a new bridge across the river.”', '[{"key":"A","text":"A new bridge is being built across the river by the workers."},{"key":"B","text":"A new bridge is built across the river by the workers."},{"key":"C","text":"A new bridge was being built across the river by the workers."},{"key":"D","text":"A new bridge has been built across the river by the workers."}]'::jsonb, 'A', 'The active sentence is in the present continuous (''are building''). Its passive is formed with is/are + being + past participle, so the correct form is ''is being built''.', 2, false, 3),
  ('49ce68a3-0fe3-4002-9b2f-b51ecff4c4a8', '0c0dab0e-9f8c-42bb-8ebb-a8ec577f81ea', null, 'Choose the correct reported (indirect) form of the sentence: She said, “I will visit my grandmother tomorrow.”', '[{"key":"A","text":"She told that she would visit her grandmother the next day."},{"key":"B","text":"She said that I would visit my grandmother the next day."},{"key":"C","text":"She said that she would visit her grandmother the next day."},{"key":"D","text":"She said that she had visited her grandmother the day before."}]'::jsonb, 'C', 'In reported speech after ''said'', ''will'' becomes ''would'', ''I/my'' become ''she/her'', and ''tomorrow'' becomes ''the next day''. ''Told'' needs an object (for example, ''told me''), so the first option is incorrect.', 2, false, 4),
  ('d8bd8522-ec67-4f2a-a721-145c7caa0abf', '0c0dab0e-9f8c-42bb-8ebb-a8ec577f81ea', null, 'Choose the correct question tag: She hardly ever comes to class late, ______?', '[{"key":"A","text":"doesn''t she"},{"key":"B","text":"isn''t she"},{"key":"C","text":"is she"},{"key":"D","text":"does she"}]'::jsonb, 'D', '''Hardly ever'' gives the statement a negative meaning, so the tag must be positive. The verb ''comes'' is in the simple present, so the auxiliary ''does'' is used: ''does she?''', 3, false, 5),
  ('2bfa7cdd-0a65-472b-b134-f8d991a39c15', '0c0dab0e-9f8c-42bb-8ebb-a8ec577f81ea', null, 'Choose the word closest in meaning to the word in capital letters: The long drought had a DETRIMENTAL effect on the harvest.', '[{"key":"A","text":"beneficial"},{"key":"B","text":"harmful"},{"key":"C","text":"temporary"},{"key":"D","text":"minor"}]'::jsonb, 'B', '''Detrimental'' means causing harm or damage. A long drought damages crops, so ''harmful'' is the closest meaning, while ''beneficial'' is its opposite.', 2, false, 6),
  ('a89c7887-4d97-4086-981f-ab1fe12aff70', '0c0dab0e-9f8c-42bb-8ebb-a8ec577f81ea', null, 'Choose the word that best completes the sentence: Almaz studied very hard for the exam; ______, she did not get the score she wanted.', '[{"key":"A","text":"therefore"},{"key":"B","text":"moreover"},{"key":"C","text":"nevertheless"},{"key":"D","text":"because"}]'::jsonb, 'C', 'The second clause is the opposite of what we would expect from the first, so a contrast connector is needed. ''Nevertheless'' (meaning ''in spite of that'') fits, whereas ''therefore'' shows a result and ''moreover'' adds information.', 1, false, 7),
  ('257e8472-038a-4860-b7ef-a408d744bdda', '0c0dab0e-9f8c-42bb-8ebb-a8ec577f81ea', null, 'Read the passage and answer the question.
